  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);

  const messages = [
    "Menyiapkan asuransi pintarmu...",
    "Mengamankan akun kamu...",
    "Mencari penawaran terbaik...",
    "Menghubungkan ke sistem...",
