                <h3 className="text-xl font-black uppercase tracking-tight">Kode Keamanan</h3>
                <p className="text-xs text-slate-500 font-medium">Masukkan 6 angka yang dikirim ke HP kamu.</p>
              </div>
              <input 
                type="tel" maxLength={6} placeholder="000000"
                className="w-full bg-transparent border-b-2 border-slate-200 dark:border-white/10 text-center text-4xl font-black tracking-[0.4em] text-brand-600 outline-none focus:border-brand-500 transition-all"
                value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
              />
              <button 
                onClick={async () => {
                  if(otp === generatedOtp) {
                    setLoading(true);
                    const newUser: DBUser = {
                      name: formData.name, email: formData.email, phone: formData.phone,
                      role: UserRole.CUSTOMER, nodeId: `SP-NODE-${Math.floor(1000+Math.random()*9000)}`,
                      verified: true, trustScore: 85, memberSince: new Date().toISOString()
                    };
                    setTimeout(() => onAuthSuccess(newUser), 1000);
                  } else {
                    setError("Kode verifikasi tidak cocok.");
                  }
                }} 
                disabled={otp.length < 6} 
                className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl active:scale-95 disabled:opacity-30"
              >
                Konfirmasi
              </button>
            </div>
          ) : (
            <form onSubmit={handleAuth} className="space-y-6">
              <div className="flex bg-slate-100 dark:bg-white/[0.05] p-1 rounded-2xl mb-2 border border-slate-200 dark:border-white/5">
                <button type="button" onClick={() => setMode('LOGIN')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${mode === 'LOGIN' ? 'bg-white dark:bg-slate-700 text-brand-600 shadow-sm' : 'text-gray-400 opacity-60'}`}>Masuk</button>
                <button type="button" onClick={() => setMode('REGISTER')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${mode === 'REGISTER' ? 'bg-white dark:bg-slate-700 text-brand-600 shadow-sm' : 'text-gray-400 opacity-60'}`}>Daftar</button>
              </div>

              <div className="space-y-5">
                {mode === 'REGISTER' && (
                  <div className="space-y-5 animate-fade-in">
                    <InputField icon={User} label="Nama Lengkap (Sesuai KTP)" value={formData.name} onChange={(v:any)=>setFormData({...formData, name: v})} placeholder="Masukkan nama asli" />
                    <InputField icon={Smartphone} label="Nomor WhatsApp" value={formData.phone} onChange={(v:any)=>setFormData({...formData, phone: v})} placeholder="0812..." />
                  </div>
                )}

                <InputField icon={Globe} label="Email" type="email" value={formData.email} onChange={(v:any)=>setFormData({...formData, email: v})} placeholder="contoh@email.com" />
                <InputField icon={KeyRound} label="Kata Sandi" type="password" value={formData.password} onChange={(v:any)=>setFormData({...formData, password: v})} showPass={showPass} setShowPass={setShowPass} placeholder="••••••••" />
