import { UserRole } from '../../types';
import { db } from '../../db';

const AdminPortal = ({ onLogout, products, setProducts, userRole }: { onLogout: () => void, products: any[], setProducts: any, userRole: UserRole }) => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const [stats, setStats] = useState({
    userCount: 0,
    policyCount: 0,
    claimCount: 0,
    totalPremium: 0
  });

  const fetchStats = async () => {
      const u = await db.users.count();
      const p = await db.policies.count();
      const c = await db.claims.count();
      const policies = await db.policies.toArray();
      const total = policies.reduce((acc, curr) => acc + curr.premium, 0);

      setStats({
          userCount: u,
          policyCount: p,
          claimCount: c,
          totalPremium: total
      });
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    fetchStats();

    const interval = setInterval(fetchStats, 10000);
    return () => {
      window.removeEventListener('resize', handleResize);
      clearInterval(interval);
    }
  }, []);

  const getMenuItems = () => {
    const common = [
      { id: 'dashboard', label: 'Dasbor Utama', icon: LayoutDashboard },
    ];

    const masterItems = [
      { id: 'security', label: 'Neural Guard (Master)', icon: ShieldAlert },
      { id: 'approvals', label: 'Semua Persetujuan', icon: ClipboardCheck },
      { id: 'users', label: 'Direktori Pengguna', icon: Users },
      { id: 'inventory', label: 'Matriks Inventaris', icon: HardDrive },
      { id: 'settings', label: 'Registri Inti', icon: Settings },
    ];

    const surepathAdminItems = [
      { id: 'approvals', label: 'Manajemen Polis', icon: ClipboardCheck },
      { id: 'users', label: 'Manajemen Pengguna', icon: UserCheck },
      { id: 'data_io', label: 'I/O Data Database', icon: Database },
      { id: 'transactions', label: 'Traffic Jaringan', icon: Zap },
    ];

    const insuranceAdminItems = [
      { id: 'approvals', label: 'Aplikasi Baru', icon: FileText },
      { id: 'data_io', label: 'Sinkronisasi Data', icon: RefreshCw },
      { id: 'inventory', label: 'Katalog Produk', icon: Building2 },
    ];

    const financeItems = [
      { id: 'ledger', label: 'Buku Besar Keuangan', icon: FileText },
      { id: 'wallet', label: 'Vault Modal', icon: Wallet },
      { id: 'approvals', label: 'Audit Pembayaran', icon: ClipboardCheck },
      { id: 'users', label: 'Informasi Nasabah', icon: Users },
    ];

    switch (userRole) {
      case UserRole.MASTER_ADMIN: return [...common, ...masterItems];
      case UserRole.ADMIN: return [...common, ...surepathAdminItems];
      case UserRole.INSURANCE_ADMIN: return [...common, ...insuranceAdminItems];
      case UserRole.FINANCE: return [...common, ...financeItems];
      default: return common;
    }
  };

  const SidebarContent = () => (
    <div className="flex flex-col h-full">
      <div className="flex items-center gap-3 mb-12 px-2">
        <div className="w-10 h-10 bg-primary-500 rounded-xl flex items-center justify-center shadow-[0_0_20px_rgba(249,115,22,0.4)]">
          <ShieldCheck size={24} className="text-white" />
        </div>
        <div>
          <h1 className="font-black text-xl tracking-tighter uppercase leading-none">Sure<span className="text-primary-500">Path</span></h1>
          <span className="text-[0.5rem] font-bold text-gray-500 uppercase tracking-[0.3em]">Neural Command HQ</span>
        </div>
      </div>

      <nav className="flex-1 space-y-1.5 overflow-y-auto no-scrollbar">
        {getMenuItems().map((item) => (
          <button
            key={item.id}
            onClick={() => { setActiveTab(item.id); setMobileMenuOpen(false); }}
            className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl transition-all duration-300 group ${
              activeTab === item.id 
                ? 'bg-primary-500/10 text-primary-500 border border-primary-500/20 shadow-[0_10px_30px_-10px_rgba(249,115,22,0.2)]' 
                : 'text-gray-500 hover:text-gray-300 hover:bg-white/5'
            }`}
          >
            <item.icon size={20} className={activeTab === item.id ? 'animate-pulse' : 'group-hover:scale-110 transition-transform'} />
            <span className="text-xs font-black uppercase tracking-widest">{item.label}</span>
          </button>
        ))}
      </nav>

      <div className="pt-6 border-t border-white/5 space-y-4">
        <div className="p-4 bg-white/5 rounded-2xl border border-white/5 text-center">
          <p className="text-[0.5rem] font-black text-gray-500 uppercase tracking-[0.2em] mb-1">Peran Sesi</p>
          <p className="text-[0.6rem] font-black uppercase text-white tracking-widest leading-none truncate">{userRole.replace('_', ' ')}</p>
        </div>
        <button 
          onClick={onLogout}
          className="w-full flex items-center gap-4 px-4 py-4 rounded-2xl text-rose-500 hover:bg-rose-500/10 transition-all border border-transparent hover:border-rose-500/20 active:scale-95 shadow-xl bg-black/40 font-black uppercase text-[0.6rem] tracking-[0.2em]"
        >
          <LogOut size={18} />
          Keluar Sesi
        </button>
      </div>
    </div>
  );

  const formatMoney = (n: number) => new Intl.NumberFormat('id-ID', { notation: "compact", compactDisplay: "short" }).format(n);

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {!isMobile && (
        <aside className="w-72 border-r border-white/5 bg-black/40 backdrop-blur-xl flex flex-col p-6 flex-shrink-0">
          <SidebarContent />
        </aside>
      )}

      {isMobile && mobileMenuOpen && (
        <div className="fixed inset-0 z-[100] animate-fade-in">
           <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setMobileMenuOpen(false)}></div>
           <aside className="absolute top-0 left-0 bottom-0 w-72 bg-[#0a0a0a] border-r border-white/10 p-6 flex flex-col animate-slide-right shadow-2xl">
              <SidebarContent />
           </aside>
        </div>
      )}

      <main className="flex-1 flex flex-col min-w-0 bg-grid-pattern relative">
        <header className="h-20 border-b border-white/5 flex items-center justify-between px-6 lg:px-10 bg-black/20 backdrop-blur-md z-10 flex-shrink-0">
          <div className="flex items-center gap-4 lg:gap-6 flex-1">
            {isMobile && (
              <button 
                onClick={() => setMobileMenuOpen(true)}
                className="p-3 bg-white/5 rounded-xl text-gray-400 hover:text-white transition-all shadow-lg"
              >
                <Menu size={20} />
              </button>
            )}
            <div className="relative w-full max-w-sm group hidden md:block">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500 group-focus-within:text-primary-500" size={18} />
              <input 
                type="text" 
                placeholder="Cari data nasabah atau polis..." 
                className="w-full bg-white/5 border border-white/5 rounded-2xl py-3 pl-12 pr-4 text-xs font-medium outline-none focus:border-primary-500/50 transition-all shadow-inner"
              />
            </div>
          </div>

          <div className="flex items-center gap-3 lg:gap-6">
             <div className="hidden xl:flex items-center gap-3 px-4 py-2 bg-emerald-500/5 border border-emerald-500/10 rounded-2xl">
                <Radio size={14} className="text-emerald-500 animate-pulse"/>
                <span className="text-[0.6rem] font-black text-emerald-500 uppercase tracking-widest leading-none">Jaringan: Optimal</span>
             </div>
            <button onClick={fetchStats} className="p-2.5 text-gray-400 hover:text-white bg-white/5 rounded-xl transition-colors shadow-lg group active:rotate-180 duration-500">
              <RefreshCw size={18} />
            </button>
            <div className="relative">
              <button 
                onClick={() => setIsProfileOpen(!isProfileOpen)}
                className="flex items-center gap-3 pl-2 pr-3 py-2 bg-white/5 rounded-2xl border border-white/5 hover:border-white/10 transition-all shadow-lg active:scale-95"
              >
                <div className="w-8 h-8 rounded-xl bg-gradient-to-tr from-primary-500 to-orange-700 flex items-center justify-center font-black text-xs shadow-inner uppercase">
                  {userRole[0]}
                </div>
                <ChevronDown size={14} className={`text-gray-500 transition-transform ${isProfileOpen ? 'rotate-180' : ''}`} />
              </button>
              {isProfileOpen && (
                <div className="absolute right-0 mt-3 w-48 bg-[#111] border border-white/10 rounded-2xl shadow-2xl p-2 animate-fade-in z-50">
                  <button onClick={onLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl text-rose-500 hover:bg-rose-500/10 transition-all text-[0.6rem] font-black uppercase tracking-widest">
                    <LogOut size={14}/> Keluar Sesi
                  </button>
                </div>
              )}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10 no-scrollbar">
          <div className="max-w-7xl mx-auto space-y-10">
            {activeTab === 'dashboard' && (
              <div className="animate-fade-in space-y-8 lg:space-y-10">
                <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end gap-4">
                   <div>
                      <p className="text-[0.6rem] lg:text-[0.7rem] font-black text-primary-500 uppercase tracking-[0.4em] mb-2">Neural HQ Pulse</p>
                      <h2 className="text-3xl lg:text-4xl font-black uppercase tracking-tighter leading-none">Kontrol <span className="text-gray-500">{userRole.replace('_', ' ')}</span></h2>
                   </div>
                   <div className="flex gap-2 w-full lg:w-auto">
                      <button className="flex-1 lg:flex-none px-4 py-2.5 bg-white/5 rounded-xl border border-white/10 text-[0.55rem] font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-white/10 transition-all"><Globe size={14}/> Simpul: JKT-01</button>
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                   <StatCard label="Total Premi Masuk" value={`Rp ${formatMoney(stats.totalPremium)}`} trend="+Live" icon={Activity} color="bg-emerald-500/10 text-emerald-500" />
                   <StatCard label="Pengguna Aktif" value={stats.userCount} trend={`+${stats.userCount}`} icon={Users} color="bg-blue-500/10 text-blue-500" />
                   <StatCard label="Total Polis" value={stats.policyCount} trend="+Live" icon={Zap} color="bg-orange-500/10 text-orange-500" />
                </div>

                <div className="pt-4">
                   <BizAdminView section="transactions" isDashboard={true} />
                </div>
              </div>
            )}

            {activeTab === 'data_io' && (
              <div className="space-y-8 animate-fade-in">
                <h3 className="text-2xl font-black uppercase tracking-tighter">Pusat <span className="text-primary-500">Data</span></h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="p-10 border-2 border-dashed border-white/10 rounded-[3rem] flex flex-col items-center justify-center text-center gap-6 group hover:border-primary-500/50 transition-all cursor-pointer">
                      <div className="w-20 h-20 bg-primary-500/10 rounded-3xl flex items-center justify-center text-primary-500 group-hover:scale-110 transition-transform"><UploadCloud size={40}/></div>
                      <div>
                         <h4 className="text-xl font-black uppercase">Unggah Dokumen Baru</h4>
                         <p className="text-xs text-gray-500 font-bold uppercase mt-2">Masal CSV/Excel atau Berkas PDF Polis</p>
                      </div>
                   </div>
                   <div className="p-10 border-2 border-dashed border-white/10 rounded-[3rem] flex flex-col items-center justify-center text-center gap-6 group hover:border-emerald-500/50 transition-all cursor-pointer">
                      <div className="w-20 h-20 bg-emerald-500/10 rounded-3xl flex items-center justify-center text-emerald-500 group-hover:scale-110 transition-transform"><DownloadCloud size={40}/></div>
                      <div>
                         <h4 className="text-xl font-black uppercase">Unduh Laporan Masal</h4>
                         <p className="text-xs text-gray-500 font-bold uppercase mt-2">Ekspor Database ke CSV/Excel/PDF</p>
                      </div>
                   </div>
                </div>
              </div>
            )}

            {activeTab === 'security' && <SecurityView />}
            {activeTab === 'approvals' && <ApprovalsView />}
            {activeTab === 'verifications' && <VerificationsView />}
            {activeTab === 'inventory' && <InventoryView />}
            {activeTab === 'settings' && <SettingsView products={products} setProducts={setProducts} />}
            {activeTab === 'ledger' && <FinanceView section="ledger" />}
            {activeTab === 'wallet' && <FinanceView section="wallet" />}
            {activeTab === 'transactions' && <BizAdminView section="transactions" />}
            {activeTab === 'users' && <BizAdminView section="users" />}
          </div>
        </div>
      </main>
    </div>
  );
};

const StatCard = ({ label, value, trend, icon: Icon, color }: any) => (
  <div className="p-8 bg-white/[0.03] border border-white/5 rounded-[2.5rem] relative overflow-hidden backdrop-blur-sm group hover:border-primary-500/30 transition-all duration-500 shadow-xl">
    <div className="flex justify-between items-start mb-6">
      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-inner ${color}`}>
        <Icon size={24} />
      </div>
      {trend && (
        <div className={`flex items-center gap-1 text-[0.65rem] font-black ${trend.startsWith('+') ? 'text-emerald-500' : 'text-rose-500'}`}>
          {trend} <ArrowUpRight size={14} className={trend.startsWith('-') ? 'rotate-90' : ''} />
        </div>
      )}
    </div>
    <p className="text-3xl font-black tracking-tighter leading-none mb-2">{value}</p>
    <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest">{label}</p>
  </div>
);

export default AdminPortal;

import React, { useState } from 'react';
import { Filter, Star, Coins, CheckCircle2, MinusCircle, ReceiptText, Check, Scale, X, ArrowRight } from 'lucide-react';
import { INSURANCE_PROVIDERS, STAMP_DUTY } from '../../constants';
import { formatIDR } from './WizardUI';

interface StepProvidersProps {
  sortBy: 'RATING' | 'PRICE';
  setSortBy: (s: 'RATING' | 'PRICE') => void;
  sortedProviders: any[];
  selectedProviderId: string | null;
  setSelectedProviderId: (id: string | null) => void;
  premiumBreakdown: any;
  showProviderBreakdown: boolean;
  setShowProviderBreakdown: (b: boolean) => void;
}

const ComparisonModal = ({ isOpen, onClose, providers, selectedIds, premiumBreakdown, onSelectProvider }: any) => {
  if (!isOpen) return null;

  const comparisonData = providers.filter((p: any) => selectedIds.includes(p.id));

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-fade-in">
       <div className="bg-white dark:bg-gray-900 w-full max-w-5xl max-h-[90vh] rounded-[3rem] overflow-hidden flex flex-col border border-white/10 shadow-2xl relative">
          <div className="p-6 border-b border-black/5 dark:border-white/5 flex justify-between items-center bg-gray-50 dark:bg-white/5">
             <div>
                <h3 className="text-xl font-black uppercase tracking-tighter">Matriks Perbandingan</h3>
                <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest">Analisa Berdampingan</p>
             </div>
             <button onClick={onClose} className="p-3 rounded-full bg-gray-200 dark:bg-white/10 hover:bg-rose-500 hover:text-white transition-all">
                <X size={20}/>
             </button>
          </div>

          <div className="flex-1 overflow-y-auto p-6 no-scrollbar bg-[#f8fafc] dark:bg-[#050505]">
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {comparisonData.map((p: any) => {
                   const price = (premiumBreakdown?.netPremium || 0) + p.adminFee + STAMP_DUTY;
                   return (
                     <div key={p.id} className="p-6 rounded-[2.5rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 flex flex-col gap-6 shadow-xl relative overflow-hidden group hover:border-primary-500/30 transition-all">
                        <div className="text-center space-y-3 relative z-10">
                           <div className="w-16 h-16 mx-auto bg-gray-100 dark:bg-white/10 rounded-2xl flex items-center justify-center shadow-sm text-2xl font-black text-gray-500 dark:text-gray-300">{p.name[0]}</div>
                           <div>
                             <h4 className="font-black text-lg uppercase tracking-tight">{p.name}</h4>
                             <div className="flex items-center justify-center gap-1.5 mt-1">
                                <Star size={12} className="fill-amber-500 text-amber-500"/>
                                <span className="text-xs font-bold">{p.rating} / 5.0</span>
                             </div>
                           </div>
                        </div>

                        <div className="space-y-3 bg-gray-50 dark:bg-black/20 p-4 rounded-2xl border border-black/5 dark:border-white/5">
                           <div className="flex justify-between items-center">
                              <span className="text-[0.55rem] font-black uppercase text-gray-400">Biaya Admin</span>
                              <span className="text-xs font-black">{formatIDR(p.adminFee)}</span>
                           </div>
                           <div className="flex justify-between items-center pt-2 border-t border-black/5 dark:border-white/5">
                              <span className="text-[0.55rem] font-black uppercase text-gray-400">Total Akhir</span>
                              <span className="text-sm font-black text-primary-500">{formatIDR(price)}</span>
                           </div>
                        </div>

                        <div className="space-y-3 flex-1">
                           <p className="text-[0.55rem] font-black uppercase text-gray-400 text-center tracking-widest">Fitur AI</p>
                           <ul className="space-y-2">
                              {p.features?.map((f: string) => (
                                 <li key={f} className="text-[0.6rem] font-bold text-center bg-gray-100 dark:bg-white/5 py-2 rounded-xl border border-black/5 dark:border-white/5 text-gray-600 dark:text-gray-300">{f}</li>
                              ))}
                           </ul>
                        </div>

                        <div className="grid grid-cols-2 gap-3 text-[0.55rem]">
                           <div className="space-y-1">
                              <span className="font-black uppercase text-emerald-500 tracking-widest block mb-1">Kelebihan</span>
                              {p.advantages?.slice(0,2).map((a: string, i: number) => (
                                <div key={i} className="flex gap-1 items-start leading-tight opacity-80"><CheckCircle2 size={8} className="text-emerald-500 mt-0.5 flex-shrink-0"/> {a}</div>
                              ))}
                           </div>
                           <div className="space-y-1">
                              <span className="font-black uppercase text-rose-500 tracking-widest block mb-1">Kekurangan</span>
                              {p.disadvantages?.slice(0,2).map((d: string, i: number) => (
                                <div key={i} className="flex gap-1 items-start leading-tight opacity-80"><MinusCircle size={8} className="text-rose-500 mt-0.5 flex-shrink-0"/> {d}</div>
                              ))}
                           </div>
                        </div>

                        <button 
                          onClick={() => onSelectProvider(p.id)}
                          className="w-full py-4 bg-midnight dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.2em] hover:scale-[1.02] active:scale-95 transition-all shadow-lg flex items-center justify-center gap-2"
                        >
                          Pilih Node Ini <ArrowRight size={14}/>
                        </button>
                     </div>
                   )
                })}
             </div>
          </div>
       </div>
    </div>
  )
}

const StepProviders: React.FC<StepProvidersProps> = ({
  sortBy, setSortBy, sortedProviders, selectedProviderId, setSelectedProviderId,
  premiumBreakdown, showProviderBreakdown, setShowProviderBreakdown
}) => {
  const [compareList, setCompareList] = useState<string[]>([]);
  const [showCompareModal, setShowCompareModal] = useState(false);

  const toggleCompare = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setCompareList(prev => 
      prev.includes(id) ? prev.filter(p => p !== id) : [...prev, id]
    );
  };

  const handleSelectFromModal = (id: string) => {
    setSelectedProviderId(id);
    setShowCompareModal(false);
    setCompareList([]);
  };

  return (
    <div className="space-y-6 animate-fade-in pb-24 relative">
       <ComparisonModal 
          isOpen={showCompareModal} 
          onClose={() => setShowCompareModal(false)}
          providers={sortedProviders}
          selectedIds={compareList}
          premiumBreakdown={premiumBreakdown}
          onSelectProvider={handleSelectFromModal}
       />

       {compareList.length > 1 && (
         <div className="fixed bottom-24 left-1/2 -translate-x-1/2 z-50 animate-pop-in">
            <button 
              onClick={() => setShowCompareModal(true)}
              className="bg-indigo-600 text-white pl-6 pr-8 py-3.5 rounded-full shadow-[0_20px_40px_-10px_rgba(79,70,229,0.5)] flex items-center gap-4 hover:scale-105 active:scale-95 transition-all border border-indigo-400/30"
            >
               <div className="bg-white/20 p-1.5 rounded-full">
                  <Scale size={18} className="text-white"/>
               </div>
               <span className="text-xs font-black uppercase tracking-widest">Bandingkan ({compareList.length})</span>
            </button>
         </div>
       )}

       <div className="flex items-center justify-between px-2 bg-gray-100 dark:bg-white/[0.03] p-3 rounded-[1.5rem] border border-black/5 dark:border-white/5">
          <div className="flex items-center gap-3 text-gray-500 ml-2">
            <Filter size={16} className="text-primary-500"/>
            <span className="text-[0.6rem] font-black uppercase tracking-[0.2em]">Urutkan Data:</span>
          </div>
          <div className="flex bg-white dark:bg-gray-800 p-1 rounded-xl shadow-sm">
             <button 
                onClick={() => setSortBy('RATING')}
                className={`px-5 py-2 rounded-lg text-[0.6rem] font-black uppercase transition-all flex items-center gap-2 ${sortBy === 'RATING' ? 'bg-primary-500 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}
             >
                <Star size={12} className={sortBy === 'RATING' ? 'fill-white' : ''}/> Rating
             </button>
             <button 
                onClick={() => setSortBy('PRICE')}
                className={`px-5 py-2 rounded-lg text-[0.6rem] font-black uppercase transition-all flex items-center gap-2 ${sortBy === 'PRICE' ? 'bg-primary-500 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}
             >
                <Coins size={12}/> Harga
             </button>
          </div>
       </div>

       <div className="space-y-5">
         {sortedProviders.map(p => {
           const finalPremi = (premiumBreakdown?.netPremium || 0) + p.adminFee + STAMP_DUTY;
           const isSelected = selectedProviderId === p.id;
           const isComparing = compareList.includes(p.id);

           return (
             <div 
               key={p.id} 
               onClick={() => setSelectedProviderId(p.id)}
               className={`p-6 rounded-[2.8rem] border-2 cursor-pointer transition-all relative overflow-hidden group tap-feedback bg-white dark:bg-white/[0.03] ${isSelected ? 'border-primary-500 shadow-2xl scale-[1.01] ring-2 ring-primary-500/10' : 'border-black/5 hover:border-black/10'}`}
             >
                <button 
                  onClick={(e) => toggleCompare(e, p.id)}
                  className={`absolute top-6 left-6 z-20 px-3 py-1.5 rounded-full flex items-center gap-2 transition-all border ${isComparing ? 'bg-indigo-500 border-indigo-500 text-white shadow-lg shadow-indigo-500/30' : 'bg-gray-100 dark:bg-white/10 border-transparent text-gray-400 hover:bg-gray-200 dark:hover:bg-white/20'}`}
                >
                   <Scale size={12}/>
                   <span className="text-[0.5rem] font-black uppercase tracking-widest">{isComparing ? 'Membandingkan' : 'Bandingkan'}</span>
                </button>

