                <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-xl border border-gray-100 dark:border-white/5">
                    <p className="text-[0.5rem] font-black uppercase text-gray-400 mb-2 tracking-widest">Rekomendasi Bengkel</p>
                    <p className="text-[0.65rem] font-bold uppercase tracking-tight text-gray-900 dark:text-white flex items-center gap-2"><MapPin size={10} className="text-primary-500"/> {claimResult.rekomendasiBengkel}</p>
                </div>
            </div>
          )}

          {activeTab === 'steps' && (
            <div className="animate-fade-in space-y-2 p-1">
                {claimResult.nextSteps.map((step, idx) => (
                    <div key={idx} className="flex gap-3 p-3 bg-emerald-50 dark:bg-emerald-950/20 rounded-xl border border-emerald-100 dark:border-emerald-900/30 items-center">
                        <div className="w-5 h-5 bg-emerald-500 text-white rounded-lg flex items-center justify-center flex-shrink-0 text-[0.6rem] font-black">{idx + 1}</div>
                        <p className="text-[0.6rem] font-bold text-emerald-900 dark:text-emerald-100 uppercase tracking-tight">{step}</p>
                    </div>
                ))}
            </div>
          )}
        </div>

        <div className="grid grid-cols-2 gap-2 pt-1 flex-shrink-0">
          <button onClick={() => setStep('docUpload')} className="py-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl font-black uppercase text-[0.55rem] tracking-widest flex items-center justify-center gap-1.5 transition-all active:scale-95 shadow-sm">
            <FileSearch size={14}/> Baca Dokumen AI
          </button>
          <button onClick={() => setStep('reporting')} className="py-3 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.55rem] tracking-widest shadow-lg shadow-primary-500/20 transition-all active:scale-95">Konfirmasi Klaim</button>
        </div>
      </div>
    );
  }

  if (step === 'docUpload') {
    return (
      <div className="space-y-4 animate-fade-in flex flex-col h-full justify-center">
        <Header title="Baca Dokumen Otomatis" showBack onBack={() => setStep('result')} />
        <div className="p-6 rounded-[2rem] border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center text-center gap-3 relative bg-gray-50 dark:bg-white/5">
          {isSummarizing ? (
            <div className="py-6 space-y-3">
              <Loader2 className="animate-spin text-primary-500 mx-auto" size={28}/>
              <p className="text-[0.55rem] font-black uppercase text-gray-400 animate-pulse">Menghubungkan ke sistem...</p>
            </div>
          ) : (
            <>
              <FileSearch size={32} className="text-gray-300"/>
              <div className="space-y-0.5">
                <p className="font-black text-xs uppercase tracking-tight">Upload Dokumen Klaim</p>
                <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-widest">KTP / STNK untuk mempercepat data</p>
              </div>
              <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleDocUpload} />
