    { role: UserRole.AGENT, label: 'Agen SurePath', email: 'agent@surepath.ai', icon: Briefcase, color: 'bg-orange-500', desc: 'Jualan & cek komisi real-time.', type: 'APP' },
    { role: UserRole.FINANCE, label: 'Manajer Keuangan', email: 'finance@surepath.ai', icon: Wallet, color: 'bg-emerald-600', desc: 'Laporan finansial & bayar klaim.', type: 'DASHBOARD' },
    { role: UserRole.ADMIN, label: 'Admin Operasional', email: 'admin@surepath.ai', icon: LayoutDashboard, color: 'bg-brand-600', desc: 'Kelola data & persetujuan polis.', type: 'DASHBOARD' },
    { role: UserRole.INSURANCE_ADMIN, label: 'Mitra Asuransi', email: 'zurich@surepath.ai', icon: Building2, color: 'bg-indigo-600', desc: 'Akses data integrasi asuransi.', type: 'DASHBOARD' },
    { role: UserRole.MASTER_ADMIN, label: 'Chief Architect', email: 'master@surepath.ai', icon: ShieldAlert, color: 'bg-rose-500', desc: 'Kontrol penuh seluruh ekosistem.', type: 'DASHBOARD' },
  ];

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#080707] flex flex-col items-center p-6 relative overflow-hidden transition-colors duration-700">

      <div className="absolute top-[-5%] right-[-10%] w-[400px] h-[400px] bg-brand-500/10 rounded-full blur-[80px] pointer-events-none"></div>
      <div className="absolute bottom-[-5%] left-[-10%] w-[400px] h-[400px] bg-blue-500/10 rounded-full blur-[80px] pointer-events-none"></div>

      {showIncomingOtp && (
