      </div>

      <div className="w-full max-w-md flex flex-col items-center space-y-8 flex-1 relative z-10">
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-4">
            <div className="p-6 bg-white dark:bg-[#111] rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-white/5 relative overflow-hidden group">
               <SurePathLogo className="w-16 h-16 relative z-10 group-hover:scale-105 transition-transform duration-500" />
               <div className="absolute inset-0 bg-gradient-to-tr from-brand-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
