              <span className="text-[0.45rem] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-[0.4em] mt-1 transition-colors duration-700">{currentUser?.name || 'Halo!'}</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-white dark:bg-slate-800 rounded-2xl text-gray-400 dark:text-gray-500 hover:text-primary-500 transition-all duration-700 shadow-sm border border-gray-100 dark:border-white/5 active:rotate-45">
              {darkMode ? <Sun size={18} className="text-yellow-400"/> : <Moon size={18}/>}
            </button>
            <button onClick={handleLogout} className="p-3 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl hover:bg-primary-500 dark:hover:bg-primary-500 transition-all duration-700 shadow-lg active:scale-95">
               <LogOut size={18}/>
            </button>
          </div>
        </header>
      )}
      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative bg-neural-mesh transition-colors duration-700 ${isWizardFlow ? 'p-0 h-screen' : 'px-6 py-8'}`}>
        {children}
      </main>
      {!isWizardFlow && currentUser && (
        <nav className="flex-shrink-0 fixed bottom-8 inset-x-6 h-20 bg-white/90 dark:bg-[#111]/90 backdrop-blur-xl z-[70] flex items-center justify-around px-4 rounded-[2.8rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] border border-gray-100 dark:border-white/10 max-w-xl mx-auto transition-all duration-500">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-1.5 flex-1 py-3 transition-all duration-300 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-primary-500 scale-110 -translate-y-1' : 'text-gray-400 dark:text-gray-600'}`}>
              <item.icon size={24} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(249,115,22,0.4)]' : ''} />
              <span className="text-[0.45rem] font-black uppercase tracking-[0.2em]">{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );

  // Perangkat Desktop: Gunakan simulator HP untuk App, Full Screen untuk Dashboard
  if (!isMobile && currentUser && (currentUser.role === UserRole.CUSTOMER || currentUser.role === UserRole.AGENT)) {
    return (
      <div className="min-h-screen bg-[#111] flex items-center justify-center p-8 overflow-hidden relative">
        <div className="absolute inset-0 bg-neural-mesh opacity-20"></div>
        <div className="relative w-[440px] h-[880px] bg-white rounded-[5rem] border-[14px] border-[#222] shadow-[0_60px_120px_-30px_rgba(0,0,0,0.8)] overflow-hidden">
           {/* Fix: Usage of AppWrapper with portal content as children */}
           <AppWrapper>{renderPortalContent()}</AppWrapper>
        </div>
      </div>
    );
  }

  /* Fix: Root usage of AppWrapper with portal content as children */
  return <AppWrapper>{renderPortalContent()}</AppWrapper>;
};

export default App;

