    const allUsers = await db.users.toArray();
    const allPolicies = await db.policies.toArray();
    setUsers(allUsers);
    setPolicies(allPolicies);
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData, section]);

  const handleImportCSV = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      const csv = event.target?.result as string;
      const lines = csv.split('\n');
      const headers = lines[0].split(',');
      const importedUsers: any[] = [];
      const defaultCreds = await hashPassword('Surepath123!');

      for (let i = 1; i < lines.length; i++) {
        if (!lines[i].trim()) continue;
        const currentline = lines[i].split(',');
        const obj: any = {};
        headers.forEach((h, index) => {
           let val = currentline[index]?.replace(/"/g, '');
           obj[h.trim()] = val;
        });

        importedUsers.push({
           name: obj.name || 'Imported User',
           email: obj.email,
           phone: obj.phone || '08',
           role: (obj.role as any) || UserRole.CUSTOMER,
           nodeId: `SP-IMP-${Math.floor(1000+Math.random()*9000)}`,
           trustScore: 85,
           memberSince: new Date().toISOString(),
