  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...messages, { role: 'user', text: userMsg }].map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        })),
        config: {
          systemInstruction: `Anda adalah SurePath Health Bot, asisten medis AI yang ramah dan empatis. 
          Tugas Anda adalah:
          1. Menjawab pertanyaan seputar kesehatan umum.
          2. Menjelaskan rincian asuransi kesehatan dengan bahasa sederhana.
          3. Selalu ingatkan bahwa Anda adalah AI dan pengguna harus berkonsultasi dengan dokter untuk diagnosa resmi.
          Gunakan Bahasa Indonesia yang santun dan profesional.`,
          temperature: 0.7,
        }
      });

      const aiText = response.text;
      setMessages(prev => [...prev, { role: 'model', text: aiText || 'Mohon maaf, simpul neural saya sedang mengalami gangguan. Bisa diulangi?' }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: 'Terjadi kesalahan koneksi ke Neural Engine.' }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <PageTransition>
      <div className="flex flex-col h-full bg-[#f8fafc] dark:bg-[#080707] transition-colors duration-700">
        <div className="px-6 pt-6 pb-4 bg-white/80 dark:bg-black/40 backdrop-blur-xl border-b border-gray-100 dark:border-white/5 flex items-center justify-between z-10">
          <div className="flex items-center gap-4">
             <button onClick={onBack} className="p-2 bg-gray-50 dark:bg-white/5 rounded-xl text-gray-400 hover:text-primary-500 transition-colors">
                <ChevronLeft size={20}/>
             </button>
             <div>
                <h3 className="text-lg font-black uppercase tracking-tighter leading-none">Health <span className="text-primary-500">Bot</span></h3>
                <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-[0.3em] mt-1">SurePath Neural Chat v1.2</p>
             </div>
          </div>
          <div className="w-10 h-10 bg-rose-500/10 rounded-xl flex items-center justify-center text-rose-500">
             <HeartPulse size={20} className="animate-pulse"/>
          </div>
        </div>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar pb-32">
          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
              <div className={`flex gap-3 max-w-[85%] ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                <div className={`w-8 h-8 rounded-xl flex-shrink-0 flex items-center justify-center shadow-sm ${m.role === 'user' ? 'bg-primary-500 text-white' : 'bg-white dark:bg-slate-800'}`}>
                  {m.role === 'user' ? <User size={16}/> : <NeuralBot className="w-6 h-6" mood="happy"/>}
                </div>
                <div className={`p-4 rounded-2xl text-sm leading-relaxed shadow-sm ${
                  m.role === 'user' 
                  ? 'bg-primary-500 text-white rounded-tr-none' 
                  : 'bg-white dark:bg-slate-900 dark:text-gray-200 border border-gray-100 dark:border-white/5 rounded-tl-none'
                }`}>
                  {m.text}
                </div>
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-start animate-pulse">
               <div className="flex gap-3 items-center bg-white dark:bg-slate-900 p-4 rounded-2xl rounded-tl-none border border-gray-100 dark:border-white/5 shadow-sm">
                  <Loader2 size={16} className="animate-spin text-primary-500"/>
                  <span className="text-[0.6rem] font-black uppercase tracking-widest text-gray-400">Bot sedang berpikir...</span>
               </div>
            </div>
          )}
        </div>

        <div className="p-6 bg-white/80 dark:bg-black/60 backdrop-blur-2xl border-t border-gray-100 dark:border-white/5 fixed bottom-0 left-0 right-0 z-20">
          <div className="max-w-2xl mx-auto flex gap-3">
            <div className="flex-1 relative">
              <input 
                type="text" 
