const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.ID }) => {
  const [lang, setLang] = useState<Language>(initialLang);
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY' | 'DEMO_SELECT'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingOtp, setShowIncomingOtp] = useState(false);
  const [statusMsg, setStatusMsg] = useState('Sistem Siap');
  const [isMobile] = useState(window.innerWidth < 1024);

  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });

  useEffect(() => {
    seedDatabase();
  }, []);

  const handleQuickDemo = async (email: string, role: UserRole) => {
    const isDashboardRole = ![UserRole.CUSTOMER, UserRole.AGENT].includes(role);
    if (isMobile && isDashboardRole) {
       setError("Akses Dashboard Admin hanya tersedia di versi Desktop.");
       return;
    }

    setLoading(true);
    setStatusMsg('Menyiapkan sesi demo Anda...');
    try {
      const user = await db.users.where('email').equals(email).first();
      if (user) {
        setTimeout(() => onAuthSuccess(user), 1000);
      } else {
        setError("Akun demo tidak ditemukan.");
        setLoading(false);
      }
    } catch (err) {
      setError("Gagal menyambungkan ke database.");
      setLoading(false);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setStatusMsg('Memverifikasi identitas Anda...');

    try {
      if (mode === 'LOGIN') {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            setTimeout(() => onAuthSuccess(user), 1000);
          } else {
            setError("Email atau kata sandi Anda salah.");
            setLoading(false);
          }
        } else {
          setError("Akun tidak ditemukan. Silakan daftar dulu ya.");
          setLoading(false);
        }
      } else {
        const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedOtp(newOtp);
        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
          setShowIncomingOtp(true);
