export const NeuralBot = ({ className = "w-24 h-24", mood = "scanning" }: { className?: string, mood?: 'happy' | 'thinking' | 'scanning' | 'wave' }) => (
  <svg viewBox="0 0 200 200" className={className} fill="none" xmlns="http://www.w3.org/2000/svg">
