    <g className="animate-float">
      {/* Body Chassis */}
      <rect x="40" y="50" width="120" height="100" rx="45" fill="url(#botGradientSmall)" stroke="#e5e7eb" strokeWidth="2" />
      <rect x="55" y="70" width="90" height="55" rx="20" fill="#111827" />

      {/* Interactive Face */}
      <g className={mood === 'scanning' ? 'animate-pulse' : ''}>
        {(mood === 'happy' || mood === 'wave') && (
          <>
            <circle cx="80" cy="90" r="7" fill="#10b981" className="animate-blink" />
            <circle cx="120" cy="90" r="7" fill="#10b981" className="animate-blink" />
            <path d="M 80 108 Q 100 118 120 108" stroke="#10b981" strokeWidth="4" strokeLinecap="round" />
          </>
        )}
        {mood === 'scanning' && (
          <>
             <rect x="65" y="90" width="25" height="6" rx="3" fill="#3b82f6" />
             <rect x="110" y="90" width="25" height="6" rx="3" fill="#3b82f6" />
             <rect x="60" y="82" width="80" height="22" rx="6" fill="#60a5fa" opacity="0.15" />
