      {/* Antenna with Ping */}
      <line x1="100" y1="50" x2="100" y2="30" stroke="#e5e7eb" strokeWidth="5" strokeLinecap="round" />
      <circle cx="100" cy="25" r="7" fill={mood === 'thinking' ? '#f59e0b' : '#10b981'} className="animate-ping" />

      {/* waving arm if mood is wave */}
