              <div className="flex items-center justify-between px-2 pt-2">
                 <div className="flex items-center gap-4">
                    <div className="relative">
                      <div className="w-16 h-16 bg-white dark:bg-slate-900 rounded-[1.8rem] shadow-xl flex items-center justify-center border border-slate-100 dark:border-white/5 overflow-hidden group transition-colors duration-700">
                         <NeuralBot className="w-12 h-12 relative group-hover:scale-110 transition-transform" mood="happy" />
                      </div>
                      <div className="absolute -bottom-1 -right-1 w-6 h-6 bg-emerald-500 rounded-full border-4 border-[#fafaf9] dark:border-[#0a0a0a] flex items-center justify-center text-[0.5rem] text-white font-black shadow-lg transition-colors duration-700">
                         {currentUser?.trustScore || 85}%
                      </div>
                    </div>
                    <div>
                       <h3 className="text-xl font-black tracking-tight text-slate-800 dark:text-white leading-none transition-colors duration-700">{timeGreeting}, {currentUser?.name.split(' ')[0]}! 👋</h3>
                       <p className="text-[0.6rem] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-widest mt-1.5 flex items-center gap-1.5 transition-colors duration-700">
