        {/* Interactive Face */}
        <g className={mood === 'scanning' ? 'animate-pulse' : ''}>
          {(mood === 'happy' || mood === 'wave') && (
            <>
              <circle cx="80" cy="90" r="7" fill={accentColor} className="animate-blink" />
              <circle cx="120" cy="90" r="7" fill={accentColor} className="animate-blink" />
              <path d="M 80 108 Q 100 118 120 108" stroke={accentColor} strokeWidth="4" strokeLinecap="round" />
