import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, Loader2, Sparkles, ShieldAlert, ChevronLeft, HeartPulse, Stethoscope, Palette, Settings2 } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { NeuralBot, PageTransition } from './car-wizard/WizardUI';

type BotTheme = 'emerald' | 'indigo' | 'lava' | 'stealth';

const HealthChat = ({ onBack }: { onBack: () => void }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'model', text: string }[]>([
    { role: 'model', text: 'Halo! Saya asisten neural SurePath. Ada yang bisa saya bantu terkait kesehatan atau polis asuransi Anda hari ini?' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [currentTheme, setCurrentTheme] = useState<BotTheme>('emerald');
  const [showThemeSelector, setShowThemeSelector] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const themes: Record<BotTheme, { 
    name: string, 
    botColor: 'emerald' | 'blue' | 'rose' | 'slate' | 'indigo' | 'purple',
    botBubble: string,
    botBorder: string,
    botIconBg: string,
    accent: string
  }> = {
    emerald: {
      name: 'Friendly',
      botColor: 'emerald',
      botBubble: 'bg-white dark:bg-emerald-950/20',
      botBorder: 'border-emerald-100 dark:border-emerald-900/30',
      botIconBg: 'bg-emerald-500',
      accent: 'text-emerald-500'
    },
    indigo: {
      name: 'Professional',
      botColor: 'indigo',
      botBubble: 'bg-white dark:bg-indigo-950/20',
      botBorder: 'border-indigo-100 dark:border-indigo-900/30',
      botIconBg: 'bg-indigo-600',
      accent: 'text-indigo-600'
    },
    lava: {
      name: 'Energetic',
      botColor: 'rose',
      botBubble: 'bg-white dark:bg-rose-950/20',
      botBorder: 'border-rose-100 dark:border-rose-900/30',
      botIconBg: 'bg-rose-500',
      accent: 'text-rose-500'
    },
    stealth: {
      name: 'Stealth Mode',
      botColor: 'slate',
      botBubble: 'bg-slate-900 dark:bg-slate-900',
      botBorder: 'border-slate-800 dark:border-slate-800',
      botIconBg: 'bg-slate-700',
      accent: 'text-slate-500'
    }
  };

  const activeTheme = themes[currentTheme];

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...messages, { role: 'user', text: userMsg }].map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        })),
        config: {
          systemInstruction: `Anda adalah SurePath Health Bot, asisten medis AI yang ramah dan empatis. 
          Tugas Anda adalah:
          1. Menjawab pertanyaan seputar kesehatan umum.
          2. Menjelaskan rincian asuransi kesehatan dengan bahasa sederhana.
          3. Selalu ingatkan bahwa Anda adalah AI dan pengguna harus berkonsultasi dengan dokter untuk diagnosa resmi.
          Gunakan Bahasa Indonesia yang santun dan profesional.`,
          temperature: 0.7,
        }
      });

      const aiText = response.text;
      setMessages(prev => [...prev, { role: 'model', text: aiText || 'Mohon maaf, simpul neural saya sedang mengalami gangguan. Bisa diulangi?' }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: 'Terjadi kesalahan koneksi ke Neural Engine.' }]);
    } finally {
      setLoading(false);
    }
  };

  return (
