                <ChevronLeft size={20}/>
             </button>
             <div>
                <h3 className="text-lg font-black uppercase tracking-tighter leading-none">Health <span className="text-primary-500">Bot</span></h3>
                <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-[0.3em] mt-1">SurePath Neural Chat v1.2</p>
             </div>
          </div>

          <div className="relative">
            <button 
              onClick={() => setShowThemeSelector(!showThemeSelector)}
              className={`p-3 rounded-2xl transition-all shadow-sm border border-gray-100 dark:border-white/5 flex items-center gap-2 active:scale-95 ${showThemeSelector ? 'bg-primary-500 text-white' : 'bg-white dark:bg-slate-800 text-gray-400'}`}
            >
               <Palette size={20}/>
            </button>

            {showThemeSelector && (
              <div className="absolute right-0 mt-3 w-48 bg-white dark:bg-slate-900 border border-gray-100 dark:border-white/10 rounded-2xl shadow-2xl p-2 z-[60] animate-pop-in">
                 <p className="text-[0.5rem] font-black text-gray-400 uppercase tracking-widest p-2 border-b border-gray-50 dark:border-white/5 mb-1">Pilih Tema Bot</p>
                 {Object.entries(themes).map(([key, t]) => (
                   <button
                     key={key}
                     onClick={() => { setCurrentTheme(key as BotTheme); setShowThemeSelector(false); }}
                     className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all ${currentTheme === key ? 'bg-gray-50 dark:bg-white/5' : 'hover:bg-gray-50 dark:hover:bg-white/5'}`}
                   >
                     <div className={`w-4 h-4 rounded-full ${t.botIconBg} border border-white/20 shadow-sm`}></div>
                     <span className={`text-[0.65rem] font-black uppercase tracking-widest ${currentTheme === key ? 'text-primary-500' : 'text-gray-500'}`}>{t.name}</span>
                   </button>
                 ))}
              </div>
            )}
          </div>
        </div>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar pb-32">
          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
              <div className={`flex gap-3 max-w-[85%] ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                <div className={`w-8 h-8 rounded-xl flex-shrink-0 flex items-center justify-center shadow-sm ${m.role === 'user' ? 'bg-primary-500 text-white' : activeTheme.botIconBg}`}>
                  {m.role === 'user' ? <User size={16}/> : <NeuralBot className="w-6 h-6" mood="happy" color={activeTheme.botColor}/>}
                </div>
                <div className={`p-4 rounded-2xl text-sm leading-relaxed shadow-sm transition-colors duration-500 ${
                  m.role === 'user' 
                  ? 'bg-primary-500 text-white rounded-tr-none' 
                  : `${activeTheme.botBubble} ${m.role === 'model' && currentTheme === 'stealth' ? 'text-gray-300' : 'text-slate-800 dark:text-gray-200'} border ${activeTheme.botBorder} rounded-tl-none`
                }`}>
                  {m.text}
                </div>
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-start animate-pulse">
               <div className={`flex gap-3 items-center ${activeTheme.botBubble} p-4 rounded-2xl rounded-tl-none border ${activeTheme.botBorder} shadow-sm`}>
                  <Loader2 size={16} className={`animate-spin ${activeTheme.accent}`}/>
                  <span className="text-[0.6rem] font-black uppercase tracking-widest text-gray-400">Bot sedang berpikir...</span>
               </div>
            </div>
          )}
        </div>

        <div className="p-6 bg-white/80 dark:bg-black/60 backdrop-blur-2xl border-t border-gray-100 dark:border-white/5 fixed bottom-0 left-0 right-0 z-20">
          <div className="max-w-2xl mx-auto flex gap-3">
            <div className="flex-1 relative">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Tanya seputar kesehatan..."
                className="w-full bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl py-4 px-5 pr-14 text-sm font-medium outline-none focus:border-primary-500 transition-all"
              />
              <button 
                onClick={handleSend}
                disabled={loading || !input.trim()}
                className={`absolute right-2 top-2 bottom-2 px-4 ${activeTheme.botIconBg} text-white rounded-xl shadow-lg active:scale-95 transition-all disabled:opacity-30`}
              >
                <Send size={18}/>
              </button>
            </div>
          </div>
          <div className="mt-4 flex items-center justify-center gap-2 opacity-40">
             <ShieldAlert size={12}/>
             <p className="text-[0.45rem] font-bold uppercase tracking-widest">Saran AI bukan pengganti diagnosa medis profesional.</p>
          </div>
        </div>
      </div>
    </PageTransition>
  );
};

