        >
          {showPass ? <EyeOff size={18}/> : <Eye size={18}/>}
        </button>
      )}
    </div>
  </div>
);

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.ID }) => {
  const [lang, setLang] = useState<Language>(initialLang);
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY' | 'DEMO_SELECT'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingOtp, setShowIncomingOtp] = useState(false);
  const [statusMsg, setStatusMsg] = useState('Sistem Siap');
  const [isMobile] = useState(window.innerWidth < 1024);

  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });

  useEffect(() => {
    seedDatabase();
  }, []);

  const handleQuickDemo = async (email: string, role: UserRole) => {
    const isDashboardRole = ![UserRole.CUSTOMER, UserRole.AGENT].includes(role);
    if (isMobile && isDashboardRole) {
       setError("Akses Dashboard Admin hanya tersedia di versi Desktop.");
       return;
    }

    setLoading(true);
    setStatusMsg('Menyiapkan sesi demo Anda...');
    try {
      const user = await db.users.where('email').equals(email).first();
      if (user) {
        setTimeout(() => onAuthSuccess(user), 1000);
      } else {
        setError("Akun demo tidak ditemukan.");
        setLoading(false);
      }
    } catch (err) {
      setError("Gagal menyambungkan ke database.");
      setLoading(false);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setStatusMsg('Memproses permintaan...');

    try {
      if (mode === 'LOGIN') {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            setStatusMsg('Identitas terverifikasi!');
            setTimeout(() => onAuthSuccess(user), 800);
          } else {
            setError("Email atau kata sandi Anda salah.");
            setLoading(false);
          }
        } else {
          setError("Akun tidak ditemukan. Silakan daftar terlebih dahulu.");
          setLoading(false);
        }
      } else {
        // Mode REGISTER: Cek apakah email sudah ada
        const existing = await db.users.where('email').equals(formData.email).first();
        if (existing) {
          setError("Email sudah terdaftar dalam sistem.");
          setLoading(false);
          return;
        }

        // Simulasi pengiriman OTP
        const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedOtp(newOtp);
        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
          setShowIncomingOtp(true);
          setStatusMsg('OTP Terkirim');
        }, 1500);
      }
    } catch (err) {
      setError("Terjadi gangguan sistem. Silakan coba lagi.");
      setLoading(false);
    }
  };

  const finalizeRegistration = async () => {
    setLoading(true);
    setError(null);
    setStatusMsg('Enkripsi data neural...');
    try {
      const { hash, salt } = await hashPassword(formData.password);
      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        passwordHash: hash,
        salt: salt,
        role: UserRole.CUSTOMER,
        nodeId: `SP-NODE-${Math.floor(1000 + Math.random() * 9000)}`,
        verified: true,
        trustScore: 85,
        memberSince: new Date().toISOString()
      };

      const id = await db.users.add(newUser);
      const userWithId = { ...newUser, id };

      setStatusMsg('Node pendaftaran aktif!');
      setTimeout(() => onAuthSuccess(userWithId), 1000);
    } catch (err) {
      setError("Gagal menyimpan data pengguna baru.");
      setLoading(false);
    }
  };

  const appRoles = [
    { role: UserRole.CUSTOMER, label: 'Sebagai Nasabah', email: 'user@surepath.ai', icon: UserCircle, color: 'bg-blue-500', desc: 'Coba beli asuransi & lapor klaim instan.' },
    { role: UserRole.AGENT, label: 'Sebagai Agen', email: 'agent@surepath.ai', icon: Briefcase, color: 'bg-orange-500', desc: 'Kelola penjualan & cek komisi real-time.' },
  ];

  const dashboardRoles = [
    { role: UserRole.FINANCE, label: 'Bagian Keuangan', email: 'finance@surepath.ai', icon: Wallet, color: 'bg-emerald-600', desc: 'Monitoring arus kas & pembayaran klaim.' },
    { role: UserRole.ADMIN, label: 'Admin Operasional', email: 'admin@surepath.ai', icon: LayoutDashboard, color: 'bg-brand-600', desc: 'Kelola database & persetujuan polis.' },
    { role: UserRole.INSURANCE_ADMIN, label: 'Pihak Asuransi', email: 'zurich@surepath.ai', icon: Building2, color: 'bg-indigo-600', desc: 'Audit data asuransi dari mitra.' },
    { role: UserRole.MASTER_ADMIN, label: 'Chief Architect', email: 'master@surepath.ai', icon: ShieldAlert, color: 'bg-rose-500', desc: 'Akses penuh ke seluruh sistem.' },
  ];

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#080707] flex flex-col items-center p-6 relative overflow-hidden transition-colors duration-700">

      <div className="absolute top-[-5%] right-[-10%] w-[400px] h-[400px] bg-brand-500/10 rounded-full blur-[80px] pointer-events-none"></div>
      <div className="absolute bottom-[-5%] left-[-10%] w-[400px] h-[400px] bg-blue-500/10 rounded-full blur-[80px] pointer-events-none"></div>

      {showIncomingOtp && (
        <div className="fixed top-6 left-6 right-6 z-[300] animate-pop-in">
           <div className="bg-slate-900/95 backdrop-blur-xl rounded-3xl p-6 shadow-2xl flex items-center gap-6 border border-white/10">
              <div className="w-14 h-14 bg-brand-500 rounded-2xl flex items-center justify-center text-white shadow-lg"><BellRing size={28}/></div>
              <div className="flex-1">
                 <p className="text-[0.6rem] font-black text-brand-400 uppercase tracking-widest mb-1">KODE KEAMANAN DITERIMA</p>
                 <div className="flex items-center gap-4">
                    <span className="text-3xl font-black text-white tracking-[0.3em] font-mono">{generatedOtp}</span>
                    <button onClick={() => { setOtp(generatedOtp); setShowIncomingOtp(false); }} className="ml-auto px-5 py-2 bg-brand-500 text-white rounded-xl text-xs font-bold">TEMPEL KODE</button>
                 </div>
              </div>
           </div>
        </div>
      )}

      <div className="w-full flex items-center justify-between mb-8 z-50">
        <div className="flex items-center gap-2">
          <div className="w-2 h-2 rounded-full bg-brand-500 animate-pulse"></div>
          <p className="text-[0.65rem] font-bold text-slate-400 uppercase tracking-widest">{statusMsg}</p>
        </div>
      </div>

      <div className="w-full max-w-md flex flex-col items-center space-y-8 flex-1 relative z-10">
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-4">
            <div className="p-6 bg-white dark:bg-[#111] rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-white/5 relative overflow-hidden group">
               <SurePathLogo className="w-16 h-16 relative z-10 group-hover:scale-105 transition-transform duration-500" />
               <div className="absolute inset-0 bg-gradient-to-tr from-brand-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
            </div>
            <div className="absolute -bottom-2 -right-2 w-10 h-10"><NeuralBot mood={loading ? 'thinking' : 'happy'} className="w-full h-full" /></div>
          </div>
          <h1 className="text-3xl font-black tracking-tighter uppercase text-slate-900 dark:text-white leading-none">Sure<span className="text-brand-600">Path</span></h1>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.3em] mt-2">Masuk ke Ekosistem Kami</p>
        </div>

        <div className="w-full bg-white dark:bg-[#0c0c0c] rounded-[3rem] p-8 shadow-xl border border-slate-100 dark:border-white/5 overflow-hidden">
          {mode === 'DEMO_SELECT' ? (
            <div className="space-y-6 animate-pop-in">
