                          <ChevronRight size={16} className="text-slate-300 group-hover:text-brand-500 transition-colors"/>
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="space-y-3 pt-2">
                    <div className="flex items-center justify-between ml-2">
                      <p className="text-[0.55rem] font-black uppercase text-gray-400 tracking-[0.2em]">Dashboard Pusat (HQ)</p>
                      {isMobile && <BadgeCheck size={14} className="text-amber-500"/>}
                    </div>
                    <div className="grid grid-cols-1 gap-2">
                      {dashboardRoles.map((dr, i) => {
                        const isDisabled = isMobile;
                        return (
                          <button 
