                          >
                            <div className={`w-10 h-10 ${dr.color} rounded-xl flex items-center justify-center text-white shadow-lg group-hover:scale-110 transition-transform`}>
                              <dr.icon size={18}/>
                            </div>
                            <div className="text-left flex-1">
                              <span className="text-xs font-black uppercase text-slate-900 dark:text-white block">{dr.label}</span>
                              <span className="text-[0.6rem] font-medium text-gray-500 mt-0.5 block line-clamp-1">{dr.desc}</span>
                            </div>
                            {!isDisabled ? (
                              <ChevronRight size={16} className="text-slate-300 group-hover:text-brand-500 transition-colors"/>
