                disabled={otp.length < 6 || loading} 
                className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl active:scale-95 disabled:opacity-30 flex items-center justify-center gap-2"
              >
                {loading && <RefreshCw size={14} className="animate-spin"/>}
                Konfirmasi Kode
              </button>
            </div>
          ) : (
            <form onSubmit={handleAuth} className="space-y-6">
              <div className="flex bg-slate-100 dark:bg-white/[0.05] p-1 rounded-2xl mb-2 border border-slate-200 dark:border-white/5">
                <button type="button" onClick={() => setMode('LOGIN')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${mode === 'LOGIN' ? 'bg-white dark:bg-slate-700 text-brand-600 shadow-sm' : 'text-gray-400 opacity-60'}`}>Sudah Ada Akun</button>
                <button type="button" onClick={() => setMode('REGISTER')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${mode === 'REGISTER' ? 'bg-white dark:bg-slate-700 text-brand-600 shadow-sm' : 'text-gray-400 opacity-60'}`}>Daftar Baru</button>
              </div>

              <div className="space-y-5">
                {mode === 'REGISTER' && (
                  <div className="space-y-5 animate-fade-in">
                    <InputField icon={User} label="Nama Lengkap" value={formData.name} onChange={(v:any)=>setFormData({...formData, name: v})} placeholder="Masukkan nama sesuai KTP" />
                    <InputField icon={Smartphone} label="Nomor WhatsApp" value={formData.phone} onChange={(v:any)=>setFormData({...formData, phone: v})} placeholder="Mulai dengan 08..." />
                  </div>
                )}

                <InputField icon={Globe} label="Alamat Email" type="email" value={formData.email} onChange={(v:any)=>setFormData({...formData, email: v})} placeholder="email@contoh.com" />
                <InputField icon={KeyRound} label="Kata Sandi" type="password" value={formData.password} onChange={(v:any)=>setFormData({...formData, password: v})} showPass={showPass} setShowPass={setShowPass} placeholder="••••••••" />
              </div>

              {error && (
                <div className="flex items-center gap-2 p-3 bg-rose-500/10 border border-rose-500/20 rounded-xl text-rose-500 animate-pop-in">
                   <AlertCircle size={16}/>
                   <p className="text-[0.65rem] font-bold uppercase">{error}</p>
                </div>
