import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, Loader2, Sparkles, ShieldAlert, ChevronLeft, HeartPulse, Stethoscope, Paperclip, X, FileText, Image as ImageIcon } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { NeuralBot, PageTransition } from './car-wizard/WizardUI';

interface Message {
  role: 'user' | 'model';
  text: string;
  attachment?: {
    data: string; // base64
    mimeType: string;
    name: string;
  };
}

const HealthChat = ({ onBack, lang }: { onBack: () => void, lang: 'ID' | 'EN' }) => {
  const [messages, setMessages] = useState<Message[]>([
    { 
      role: 'model', 
      text: lang === 'ID' 
        ? 'Halo! Saya asisten kesehatan SurePath. Ada yang bisa saya bantu terkait keluhan kesehatan, hasil lab, atau pertanyaan polis asuransi Anda?' 
        : 'Hello! I am your SurePath health assistant. How can I help you with health concerns, lab results, or insurance policy questions?' 
    }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [file, setFile] = useState<{ data: string, mimeType: string, name: string } | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, loading]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    if (selectedFile.size > 5 * 1024 * 1024) {
      alert(lang === 'ID' ? 'Ukuran file maksimal 5MB.' : 'Max file size is 5MB.');
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      setFile({
        data: (reader.result as string).split(',')[1],
        mimeType: selectedFile.type,
        name: selectedFile.name
      });
    };
    reader.readAsDataURL(selectedFile);
  };

  const handleSend = async () => {
    if ((!input.trim() && !file) || loading) return;

    const userMsgText = input.trim();
    const currentFile = file;

    setInput('');
    setFile(null);

    const newUserMsg: Message = { 
      role: 'user', 
      text: userMsgText || (lang === 'ID' ? 'Mohon analisa dokumen ini.' : 'Please analyze this document.'),
      attachment: currentFile || undefined
    };

    setMessages(prev => [...prev, newUserMsg]);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Prepare contents for Gemini
      // We only send the image in the current turn to save tokens/complexity, 
      // but text history is maintained.
      const chatHistory = messages.map(m => ({
        role: m.role,
        parts: [{ text: m.text }]
      }));

      const currentParts: any[] = [{ text: newUserMsg.text }];
      if (currentFile) {
        currentParts.push({
          inlineData: {
            data: currentFile.data,
            mimeType: currentFile.mimeType
          }
        });
      }

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          ...chatHistory,
          { role: 'user', parts: currentParts }
        ],
        config: {
          systemInstruction: `You are SurePath Health Bot, a warm and helpful AI medical assistant. 
          Your goals:
          1. Provide general health information.
          2. ANALYZE MEDICAL DOCUMENTS: If a user uploads lab results, doctor's notes, or prescriptions, identify key values, clinical impressions, and explain them in simple terms.
          3. Explain insurance coverage terms if asked.
          4. ALWAYS include a disclaimer: "This is an AI analysis, not a clinical diagnosis. Please consult a professional doctor for medical decisions."
          Language: ${lang === 'ID' ? 'Bahasa Indonesia' : 'English'}. Be professional yet empathetic.`,
          temperature: 0.5,
        }
      });

      const aiText = response.text;
      setMessages(prev => [...prev, { role: 'model', text: aiText || '...' }]);
    } catch (error) {
      console.error("Gemini Health Error:", error);
      setMessages(prev => [...prev, { role: 'model', text: lang === 'ID' ? 'Maaf, koneksi ke pusat otak AI terputus.' : 'Sorry, connection to the AI brain was interrupted.' }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <PageTransition>
      <div className="flex flex-col h-full bg-[#fafaf9] dark:bg-[#080707] transition-all duration-700">
        {/* Chat Header */}
        <div className="px-6 pt-6 pb-4 bg-white/80 dark:bg-black/40 backdrop-blur-xl border-b border-gray-100 dark:border-white/5 flex items-center justify-between z-50">
          <div className="flex items-center gap-4">
             <button onClick={onBack} className="p-2 bg-gray-50 dark:bg-white/5 rounded-xl text-gray-400 hover:text-primary-500 transition-colors">
                <ChevronLeft size={20}/>
             </button>
             <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center text-white shadow-lg shadow-emerald-500/20">
                   <HeartPulse size={22}/>
                </div>
                <div>
                   <h3 className="text-lg font-black uppercase tracking-tighter leading-none text-slate-800 dark:text-white">Health <span className="text-primary-500">Bot</span></h3>
                   <p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-[0.3em] mt-1">AI Medical Node • Online</p>
                </div>
             </div>
          </div>
          <div className="flex gap-2">
             <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
          </div>
        </div>

        {/* Messages area */}
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar pb-40">
          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
              <div className={`flex gap-3 max-w-[85%] ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                <div className={`w-8 h-8 rounded-xl flex-shrink-0 flex items-center justify-center shadow-sm ${m.role === 'user' ? 'bg-primary-500 text-white' : 'bg-emerald-500 text-white'}`}>
                  {m.role === 'user' ? <User size={16}/> : <Bot size={16}/>}
                </div>
                <div className="space-y-2">
                  {m.attachment && (
                    <div className={`rounded-2xl overflow-hidden border border-gray-200 dark:border-white/10 shadow-sm ${m.role === 'user' ? 'ml-auto' : 'mr-auto'} max-w-[200px]`}>
                      {m.attachment.mimeType.startsWith('image/') ? (
                        <img src={`data:${m.attachment.mimeType};base64,${m.attachment.data}`} alt="attachment" className="w-full h-auto object-cover" />
                      ) : (
                        <div className="p-4 bg-white dark:bg-white/5 flex items-center gap-2">
                          <FileText size={20} className="text-primary-500"/>
                          <span className="text-[0.6rem] font-bold truncate max-w-[120px]">{m.attachment.name}</span>
                        </div>
                      )}
                    </div>
                  )}
                  <div className={`p-4 rounded-2xl text-sm leading-relaxed shadow-sm ${
                    m.role === 'user' 
                    ? 'bg-primary-500 text-white rounded-tr-none' 
                    : 'bg-white dark:bg-emerald-950/20 text-slate-800 dark:text-gray-200 border border-gray-100 dark:border-emerald-900/30 rounded-tl-none'
                  }`}>
                    {m.text}
                  </div>
                </div>
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-start animate-pulse">
               <div className="flex gap-3 items-center bg-white dark:bg-emerald-950/20 p-4 rounded-2xl rounded-tl-none border border-gray-100 dark:border-emerald-900/30">
                  <Loader2 size={16} className="animate-spin text-primary-500"/>
                  <span className="text-[0.6rem] font-black uppercase tracking-widest text-gray-400">{lang === 'ID' ? 'AI Sedang Menganalisa...' : 'AI Analyzing...'}</span>
               </div>
            </div>
          )}
        </div>

        {/* Input area */}
        <div className="p-6 bg-white/80 dark:bg-black/60 backdrop-blur-2xl border-t border-gray-100 dark:border-white/5 fixed bottom-0 left-0 right-0 z-[100]">
          <div className="max-w-3xl mx-auto space-y-4">
            {file && (
              <div className="flex items-center gap-3 p-3 bg-primary-500/10 border border-primary-500/20 rounded-2xl animate-pop-in">
                 <div className="w-10 h-10 bg-primary-500 rounded-lg flex items-center justify-center text-white">
                    {file.mimeType.startsWith('image/') ? <ImageIcon size={20}/> : <FileText size={20}/>}
                 </div>
                 <div className="flex-1 min-w-0">
                    <p className="text-[0.6rem] font-black uppercase text-primary-600 tracking-widest leading-none mb-1">{lang === 'ID' ? 'Lampiran Siap' : 'Attachment Ready'}</p>
                    <p className="text-xs font-bold text-slate-700 dark:text-slate-300 truncate">{file.name}</p>
                 </div>
                 <button onClick={() => setFile(null)} className="p-2 text-gray-400 hover:text-rose-500 transition-colors">
                    <X size={18}/>
                 </button>
              </div>
            )}

            <div className="flex gap-3">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-4 bg-gray-100 dark:bg-white/5 text-gray-500 hover:text-primary-500 rounded-2xl border border-gray-200 dark:border-white/10 transition-all active:scale-95 shadow-sm"
              >
                <Paperclip size={22}/>
              </button>
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept="image/*,application/pdf"
                onChange={handleFileChange}
              />
              <div className="flex-1 relative">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                  placeholder={lang === 'ID' ? "Tanya kesehatan atau upload lab..." : "Ask health query or upload lab results..."}
                  className="w-full bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-2xl py-4 px-5 pr-14 text-sm font-medium outline-none focus:border-primary-500 transition-all shadow-inner"
                />
                <button 
                  onClick={handleSend}
                  disabled={loading || (!input.trim() && !file)}
                  className="absolute right-2 top-2 bottom-2 px-4 bg-primary-500 text-white rounded-xl shadow-lg active:scale-95 transition-all disabled:opacity-30"
                >
                  <Send size={18}/>
                </button>
              </div>
            </div>
          </div>
          <div className="mt-4 flex items-center justify-center gap-2 opacity-40">
             <ShieldAlert size={12}/>
             <p className="text-[0.45rem] font-bold uppercase tracking-widest">{lang === 'ID' ? 'Saran AI bukan pengganti diagnosa medis resmi.' : 'AI advice is not a replacement for official medical diagnosis.'}</p>
          </div>
        </div>
      </div>
    </PageTransition>
  );
};

export default HealthChat;

