  const messages = lang === Language.ID ? [
    "Menyapa Server...",
    "Menyiapkan Proteksi Pintar...",
    "Mengecek Penawaran Terbaik...",
    "Koneksi Aman...",
    "Selesai!"
  ] : [
    "Greeting Server...",
    "Preparing Smart Protection...",
    "Checking Best Offers...",
    "Secure Connection...",
    "Done!"
