const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [lang, setLang] = useState<Language>(Language.EN);
  const [latestPolicy, setLatestPolicy] = useState<Policy | null>(null);

  const products = useMemo(() => INITIAL_PRODUCTS(lang), [lang]);

  const timeGreeting = useMemo(() => {
    const hour = new Date().getHours();
    if (lang === Language.ID) {
        if (hour < 11) return "Selamat Pagi";
        if (hour < 15) return "Selamat Siang";
        if (hour < 19) return "Selamat Sore";
        return "Selamat Malam";
    } else {
        if (hour < 12) return "Good Morning";
        if (hour < 17) return "Good Afternoon";
        return "Good Evening";
    }
  }, [lang]);

  useEffect(() => {
    const detectLanguage = () => {
      const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const isIndonesia = timezone.toLowerCase().includes('jakarta') || 
                          timezone.toLowerCase().includes('makassar') || 
                          timezone.toLowerCase().includes('jayapura');

      const savedLang = localStorage.getItem('SUREPATH_LANG') as Language;
      if (savedLang) {
        setLang(savedLang);
      } else {
        setLang(isIndonesia ? Language.ID : Language.EN);
      }
    };
    detectLanguage();
  }, []);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
        db.policies.where('userId').equals(user.id).toArray().then(res => {
           if (res.length > 0) setLatestPolicy(res.sort((a,b) => b.id! - a.id!)[0]);
        });
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, [currentPage]);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleDemoLogin = async () => {
    const user = await db.users.where('email').equals('user@surepath.ai').first();
    if (user) handleAuthSuccess(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  const startClaimFromPolicy = (policy: Policy) => setPage('claim');

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

