      <div className={darkMode ? 'dark' : ''}>
        <Navbar lang={lang} setLang={handleLangChange} darkMode={darkMode} setDarkMode={setDarkMode} currentPage={currentPage} setPage={setPage} />
        <DesktopWebsite onEnterPortal={() => { setAppMode(true); setPage('auth'); }} onAdminAccess={() => { setAppMode(true); setPage('auth'); }} currentLang={lang} onLangChange={handleLangChange} />
