const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);

  const messages = [
    "Menyapa Anda...",
    "Menyiapkan proteksi terbaik...",
    "Mengecek penawaran spesial...",
    "Sistem siap melayani...",
    "Mari melangkah bersama!"
  ];

  useEffect(() => {
    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 2.5)), 40);
    const msgTimer = setInterval(() => setMessageIdx(i => (i < messages.length - 1 ? i + 1 : i)), 700);
    const finishTimer = setTimeout(onFinish, 3000);
    return () => { clearInterval(timer); clearInterval(msgTimer); clearTimeout(finishTimer); };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[5000] bg-white dark:bg-slate-950 flex flex-col items-center justify-center overflow-hidden transition-colors duration-700">
      <div className="relative z-10 flex flex-col items-center animate-pop-in">
        <div className="mb-12 relative group">
           <div className="absolute inset-0 bg-primary-500/10 rounded-full blur-[80px] animate-pulse scale-150"></div>
           <NeuralBot className="w-44 h-44 relative" mood="happy" />
        </div>
        <div className="text-center space-y-6">
          <h1 className="text-4xl font-black tracking-tight text-slate-900 dark:text-white uppercase leading-none">
            SURE<span className="text-primary-500">PATH</span>
          </h1>
          <div className="space-y-4">
            <p className="text-[0.7rem] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-[0.3em] h-4 transition-all duration-500">
               {messages[messageIdx]}
            </p>
            <div className="w-56 h-1.5 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden mx-auto shadow-inner">
                <div className="h-full bg-primary-500 shadow-[0_0_10px_rgba(249,115,22,0.4)] transition-all duration-300" style={{ width: `${progress}%` }}></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const INITIAL_PRODUCTS = [
  { id: 'car', title: 'Asuransi Mobil', label: 'Mobil', icon: Car, color: 'text-blue-500', active: true, tech: 'Klaim Lewat Foto' },
  { id: 'travel', title: 'Perjalanan', label: 'Travel', icon: Plane, color: 'text-emerald-500', active: true, tech: 'Aktif Seketika' },
  { id: 'pa', title: 'Kecelakaan Diri', label: 'Kesehatan', icon: Heart, color: 'text-rose-500', active: true, tech: 'Proteksi Lengkap' },
  { id: 'mpar', title: 'Proteksi Barang', label: 'Barang', icon: Package, color: 'text-amber-500', active: true, tech: 'Gadget & Elektronik' },
];

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [products] = useState(INITIAL_PRODUCTS);
  const [lang, setLang] = useState<Language>(Language.ID);
  const [latestPolicy, setLatestPolicy] = useState<Policy | null>(null);

  const timeGreeting = useMemo(() => {
    const hour = new Date().getHours();
    if (hour < 11) return "Selamat Pagi";
    if (hour < 15) return "Selamat Siang";
    if (hour < 19) return "Selamat Sore";
    return "Selamat Malam";
  }, []);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
        db.policies.where('userId').equals(user.id).toArray().then(res => {
           if (res.length > 0) setLatestPolicy(res.sort((a,b) => b.id! - a.id!)[0]);
        });
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, [currentPage]);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  if (currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE].includes(currentUser.role)) {
    return <AdminPortal onLogout={handleLogout} products={products} setProducts={() => {}} userRole={currentUser.role} />;
  }

  if (!isMobile && !appMode && !currentUser) {
    return (
      <div className={darkMode ? 'dark' : ''}>
        <Navbar lang={lang} setLang={setLang} darkMode={darkMode} setDarkMode={setDarkMode} currentPage={currentPage} setPage={setPage} />
        <DesktopWebsite onEnterPortal={() => { setAppMode(true); setPage('auth'); }} onAdminAccess={() => { setAppMode(true); setPage('auth'); }} currentLang={lang} onLangChange={setLang} />
      </div>
    );
  }

  if (!currentUser && (isMobile || appMode)) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} />;
  }

  const renderPortalContent = () => {
    switch(currentPage) {
      case 'home':
        return (
          <PageTransition>
            <div className="space-y-8 pb-32 relative z-10">
              {/* FRIENDLY GREETING */}
              <div className="flex items-center justify-between px-2 pt-2">
                 <div className="flex items-center gap-4">
                    <div className="relative group cursor-pointer" onClick={() => setPage('profile')}>
                      <div className="w-16 h-16 bg-white dark:bg-slate-900 rounded-[2rem] shadow-xl flex items-center justify-center border border-slate-100 dark:border-white/5 overflow-hidden transition-all duration-500 group-hover:scale-105 active:scale-95">
                         <div className="w-full h-full bg-gradient-to-tr from-slate-50 to-slate-100 dark:from-slate-800 dark:to-slate-900 flex items-center justify-center text-3xl font-black text-slate-300 dark:text-slate-700">
                           {currentUser?.name?.[0]}
                         </div>
                      </div>
                      <div className="absolute -bottom-1 -right-1 w-6 h-6 bg-emerald-500 rounded-full border-4 border-white dark:border-slate-900 flex items-center justify-center shadow-lg">
                        <CheckCircle2 size={12} className="text-white" />
                      </div>
                    </div>
                    <div>
                       <h3 className="text-xl font-black tracking-tight text-slate-800 dark:text-white leading-none">{timeGreeting}, {currentUser?.name.split(' ')[0]}!</h3>
                       <p className="text-[0.65rem] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-widest mt-1.5 flex items-center gap-1.5">
                          <ShieldCheck size={12}/> Akun Anda Aman & Aktif
                       </p>
                    </div>
                 </div>
                 <button onClick={() => setPage('profile')} className="p-3 bg-white dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-white/5 text-slate-400 dark:text-slate-600 shadow-sm hover:text-primary-500 transition-all relative active:scale-90">
                    <Bell size={20}/>
                    <span className="absolute top-3 right-3 w-2 h-2 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800"></span>
                 </button>
              </div>

