                    <p className="font-black text-sm uppercase text-slate-800 dark:text-white">Beli Proteksi</p>
                    <p className="text-[0.55rem] text-slate-400 font-bold uppercase mt-1 tracking-widest">Pilihan Lengkap</p>
                 </div>
                 <div onClick={() => setPage('claim')} className="p-6 glass-card rounded-[2.5rem] cursor-pointer group hover:-translate-y-1 transition-all active:scale-95 relative overflow-hidden">
                    <div className="w-12 h-12 bg-rose-50 dark:bg-rose-500/10 rounded-2xl flex items-center justify-center text-rose-500 mb-4 shadow-inner"><Zap size={24}/></div>
                    <p className="font-black text-sm uppercase text-slate-800 dark:text-white">Ajukan Klaim</p>
                    <p className="text-[0.55rem] text-slate-400 font-bold uppercase mt-1 tracking-widest">Cepat & Mudah</p>
                 </div>
              </div>

              {/* LATEST POLICY CARD */}
              {latestPolicy && (
                <div className="px-1">
                  <div className="p-8 bg-slate-900 rounded-[3rem] text-white relative overflow-hidden shadow-2xl border border-white/5 group">
                     <div className="absolute top-0 right-0 p-10 opacity-5 rotate-12 group-hover:rotate-0 transition-transform duration-1000">
                        {latestPolicy.type === 'CAR' ? <Car size={160}/> : <Plane size={160}/>}
                     </div>
                     <div className="relative z-10 space-y-8">
                        <div className="flex justify-between items-start">
                           <div className="space-y-1">
                              <p className="text-[0.6rem] font-black text-primary-400 uppercase tracking-[0.4em]">Polis Aktif</p>
                              <h4 className="text-2xl font-black uppercase tracking-tighter">{latestPolicy.coverageDetails?.vehicle?.brand || 'Proteksi'} {latestPolicy.coverageDetails?.vehicle?.model || 'Saya'}</h4>
                           </div>
                           <div className="p-3 bg-white/10 rounded-2xl border border-white/10 backdrop-blur-md shadow-xl"><ShieldCheck size={24} className="text-emerald-400"/></div>
                        </div>
                        <div className="flex justify-between items-end">
                           <div className="space-y-1">
                              <p className="text-[0.5rem] font-black text-slate-500 uppercase tracking-widest">Berlaku Hingga</p>
                              <p className="text-sm font-black text-emerald-400">{new Date(latestPolicy.endDate).toLocaleDateString('id-ID', { month: 'long', year: 'numeric' })}</p>
                           </div>
                           <button onClick={() => setPage('profile')} className="px-6 py-2.5 bg-white text-slate-900 rounded-xl font-black uppercase text-[0.6rem] tracking-widest shadow-xl active:scale-95 transition-all">Kelola</button>
