                  <div key={p.id} onClick={() => setPage(`buy-${p.id}`)} className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 flex items-center justify-between active:scale-[0.98] transition-all duration-500 cursor-pointer shadow-lg hover:border-primary-500/30 group">
