// Friendly Assistant Component (Rebranded NeuralBot)
export const NeuralBot = ({ 
  className = "w-24 h-24", 
  mood = "happy",
  color = "emerald" 
}: { 
  className?: string, 
  mood?: 'happy' | 'thinking' | 'scanning' | 'wave',
  color?: 'emerald' | 'blue' | 'rose' | 'amber' | 'primary'
}) => {
  const colorMap = {
    emerald: '#10b981',
    blue: '#3b82f6',
    rose: '#f43f5e',
    amber: '#f59e0b',
    primary: '#f97316'
  };

  const accentColor = colorMap[color] || colorMap.primary;

  return (
    <svg viewBox="0 0 200 200" className={className} fill="none" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <filter id="assistantShadow" x="-20%" y="-20%" width="140%" height="140%">
          <feDropShadow dx="0" dy="8" stdDeviation="12" floodColor="rgba(0,0,0,0.1)" />
        </filter>
        <linearGradient id="bodyGradient" x1="0" y1="0" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#ffffff" />
          <stop offset="100%" stopColor="#f8fafc" />
        </linearGradient>
      </defs>

      <g className="animate-float" filter="url(#assistantShadow)">
        {/* Rounded Modern Body */}
        <circle cx="100" cy="100" r="80" fill="url(#bodyGradient)" stroke="#e2e8f0" strokeWidth="1" />

        {/* Soft "Face" Area */}
        <rect x="50" y="70" width="100" height="50" rx="25" fill="#1e293b" />

        {/* Eyes & Smile */}
        {mood === 'happy' && (
          <>
            <circle cx="80" cy="95" r="6" fill={accentColor} className="animate-pulse" />
            <circle cx="120" cy="95" r="6" fill={accentColor} className="animate-pulse" />
            <path d="M 85 108 Q 100 120 115 108" stroke={accentColor} strokeWidth="4" strokeLinecap="round" />
          </>
        )}
        {mood === 'scanning' && (
          <>
            <rect x="70" y="90" width="60" height="4" rx="2" fill={accentColor} className="animate-pulse" />
            <rect x="60" y="80" width="80" height="25" rx="12" fill={accentColor} opacity="0.1" />
          </>
        )}
        {mood === 'thinking' && (
          <g className="fill-slate-400">
            <circle cx="80" cy="95" r="5" className="animate-bounce" />
            <circle cx="100" cy="95" r="5" className="animate-bounce delay-100" />
            <circle cx="120" cy="95" r="5" className="animate-bounce delay-200" />
          </g>
        )}

        {/* Antennas / Ears */}
        <path d="M 60 45 Q 40 30 55 20" stroke="#cbd5e1" strokeWidth="6" strokeLinecap="round" />
        <path d="M 140 45 Q 160 30 145 20" stroke="#cbd5e1" strokeWidth="6" strokeLinecap="round" />
        <circle cx="55" cy="20" r="6" fill={accentColor} className="animate-pulse" />
      </g>
    </svg>
  );
};

