import React from 'react';
import { 
  FileText, Trash2, Camera, Loader2, AlertTriangle, Check, 
  RefreshCw, Info, ShieldCheck, Activity, Car, CheckCircle2, ImagePlus,
  Zap, Droplets, Lightbulb, FileSearch
} from 'lucide-react';
import { ScannerOverlay, NeuralProcessingView, PageTransition } from './WizardUI';
import { validateVehiclePhoto, analyzeVehicleSurvey, extractStnkData } from '../../services/geminiService';

interface StepSurveyProps {
  survey: any;
  setSurvey: (s: any) => void;
  stnkResult: any;
  setStnkResult: (r: any) => void;
  loading: boolean;
  setLoading: (l: boolean) => void;
  loadingType: 'KTP' | 'STNK' | 'SURVEY' | null;
  setLoadingType: (t: 'KTP' | 'STNK' | 'SURVEY' | null) => void;
  photoValidation: Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string, recommendation?: string }>;
  setPhotoValidation: React.Dispatch<React.SetStateAction<Record<string, { status: 'LOADING' | 'VALID' | 'INVALID', msg?: string, recommendation?: string }>>>;
  vehicle: any;
}

const StepSurvey: React.FC<StepSurveyProps> = ({
  survey, setSurvey, stnkResult, setStnkResult, loading, setLoading, loadingType, setLoadingType,
  photoValidation, setPhotoValidation, vehicle
}) => {

  const getRecommendation = (issue: string): string => {
    const lowIssue = issue.toLowerCase();
    if (lowIssue.includes('gelap') || lowIssue.includes('cahaya')) return "Cari tempat yang lebih terang atau nyalakan lampu ya.";
    if (lowIssue.includes('buram') || lowIssue.includes('fokus')) return "Pastikan lensa kamera bersih dan mobil tidak bergerak.";
    if (lowIssue.includes('mobil') || lowIssue.includes('bukan')) return "Pastikan yang difoto adalah mobil Anda.";
    return "Coba ambil foto ulang dengan pencahayaan yang lebih baik.";
  };

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const mimeType = file.type;
    setLoading(true);
    setLoadingType('STNK');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey((prev: any) => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64, mimeType);
      setLoading(false);
      setLoadingType(null);
      if (response.success && response.data) {
        setStnkResult({
          ownerName: response.data.owner || 'NAMA TIDAK TERDETEKSI',
          plate: response.data.plate || 'PLAT TIDAK TERDETEKSI',
          vin: response.data.vin || 'VIN TIDAK TERDETEKSI',
          engine: response.data.engine || 'ENGINE TIDAK TERDETEKSI',
          color: response.data.color || 'WARNA TIDAK TERDETEKSI',
          year: response.data.year || vehicle.year.toString(),
          status: response.data.status
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handlePhotoUpload = async (file: File, slotId: string, slotLabel: string) => {
    if (!file) return;
    const localUrl = URL.createObjectURL(file);
    setSurvey((prev: any) => ({ ...prev, photos: { ...prev.photos, [slotId]: localUrl } }));
    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = e.target?.result as string;
      setSurvey((prev: any) => ({ ...prev, photos: { ...prev.photos, [slotId]: base64 } }));
      setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'LOADING' } }));
      try {
        const result = await validateVehiclePhoto(base64, slotLabel);
        setPhotoValidation(prev => ({ 
          ...prev, 
          [slotId]: { 
            status: result.valid ? 'VALID' : 'INVALID', 
            msg: result.issue,
            recommendation: result.valid ? undefined : getRecommendation(result.issue || '')
          } 
        }));
      } catch (e) {
        setPhotoValidation(prev => ({ ...prev, [slotId]: { status: 'VALID' } }));
      }
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    const photoEntries = Object.entries(survey.photos).map(([id, data]) => ({ id, data: data as string }));
    if (photoEntries.length < 5) {
      alert("Harap lengkapi semua foto mobil ya.");
      return;
    }
    setLoading(true);
    setLoadingType('SURVEY');
    const expectedData = { brand: vehicle.brand, model: vehicle.model, color: stnkResult?.color || "Sesuai", plate: vehicle.plate };
    try {
      const response = await analyzeVehicleSurvey(photoEntries, expectedData);
      setLoading(false);
      setLoadingType(null);
      if (response.success) {
        const finalScore = response.score || 0;
        const isRejected = response.auditVerdict === 'REJECTED';
        const needsManual = (finalScore < 80 || response.auditVerdict === 'REVIEW_REQUIRED') && !isRejected;
        setSurvey((prev: any) => ({ 
          ...prev, score: finalScore, summary: response.summary || '',
          underwritingReport: response.underwritingReport || '', verdict: isRejected ? 'REJECTED' : (needsManual ? 'MANUAL_REQUIRED' : 'CLEAN'),
          rejectionReason: response.rejectionReason || (isRejected ? 'Mobil sepertinya tidak sesuai data.' : ''),
          isDirty: response.isDirty || false, manualVerif: needsManual
        }));
      }
    } catch (err) {
      setLoading(false);
      setLoadingType(null);
      alert("Gagal terhubung ke asisten AI. Coba lagi ya.");
    }
  };

  const photoSlots = [
    { id: 'front', label: 'Depan Serong' },
    { id: 'back', label: 'Belakang Serong' },
    { id: 'right', label: 'Sisi Kanan' },
    { id: 'left', label: 'Sisi Kiri' },
    { id: 'interior', label: 'Dashboard' }
  ];

  return (
    <PageTransition>
      <div className="space-y-6 pb-24">
        <div className="px-2">
           <h2 className="text-2xl font-black uppercase tracking-tighter">Verifikasi <span className="text-primary-500">Mobil Anda</span></h2>
           <p className="text-xs text-gray-500 font-medium mt-1">Hanya butuh beberapa foto agar proteksi segera aktif.</p>
        </div>

        {!survey.stnk ? (
          <div className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 space-y-6 shadow-xl relative overflow-hidden">
              <div className="flex items-center gap-4 mb-2">
                  <div className="w-10 h-10 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500 shadow-inner"><FileText size={20}/></div>
                  <div><h4 className="text-[0.7rem] font-black uppercase tracking-widest">Registrasi STNK</h4><p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Proses Instan via AI</p></div>
              </div>
              <label className="group relative aspect-[4/1] rounded-[2rem] border-2 border-dashed border-slate-200 dark:border-white/10 flex flex-col items-center justify-center gap-2 cursor-pointer hover:border-primary-500/50 transition-all bg-slate-50 dark:bg-white/[0.02]">
                  {loading && loadingType === 'STNK' ? <ScannerOverlay label="Membaca STNK..." /> : (
                  <>
                      <FileSearch size={32} className="text-slate-300 group-hover:text-primary-500 transition-colors"/>
                      <p className="text-[0.6rem] font-black uppercase tracking-widest text-slate-500">Upload Foto STNK</p>
                      <input type="file" accept="image/*" className="hidden" onChange={handleStnkUpload} />
                  </>
                  )}
              </label>
          </div>
        ) : (
          <div className="flex items-center justify-between p-4 bg-emerald-500/5 rounded-2xl border border-emerald-500/20">
              <div className="flex items-center gap-3">
                  <div className="p-2 bg-emerald-500 rounded-lg text-white"><Check size={14} strokeWidth={3}/></div>
                  <span className="text-[0.6rem] font-black text-emerald-800 dark:text-emerald-200 uppercase tracking-widest">STNK Berhasil Dibaca: {stnkResult.plate}</span>
              </div>
              <button onClick={() => setSurvey({...survey, stnk: null})} className="text-slate-400 hover:text-rose-500 transition-colors"><Trash2 size={16}/></button>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4">
           {photoSlots.map((slot) => {
              const val = photoValidation[slot.id];
              const hasPhoto = !!survey.photos[slot.id];
              return (
              <div key={slot.id} className="space-y-2">
                <div className={`group relative aspect-video rounded-[2rem] border-2 border-dashed transition-all flex flex-col items-center justify-center p-4 text-center overflow-hidden shadow-sm ${hasPhoto ? (val?.status === 'INVALID' ? 'border-rose-500 bg-rose-50' : 'border-primary-500 bg-primary-50') : 'border-slate-200 bg-white dark:bg-slate-900'}`}>
                  {hasPhoto ? (
                    <>
                        <img src={survey.photos[slot.id]} className="absolute inset-0 w-full h-full object-cover rounded-[1.8rem]" alt={slot.label} />
                        {val?.status === 'LOADING' && (
                          <div className="absolute inset-0 bg-white/70 dark:bg-black/70 flex flex-col items-center justify-center gap-2">
                              <Loader2 size={24} className="animate-spin text-primary-500"/>
                              <span className="text-[0.5rem] font-black uppercase tracking-widest">Mengecek...</span>
                          </div>
                        )}
                        {val?.status === 'INVALID' && (
                          <div className="absolute inset-0 bg-rose-500/80 flex flex-col items-center justify-center text-white p-3 text-center">
                              <AlertTriangle size={20} className="mb-1"/>
                              <span className="text-[0.5rem] font-black uppercase leading-tight">{val.msg || 'Foto Bermasalah'}</span>
                          </div>
                        )}
                        <button onClick={() => { const n = {...survey.photos}; delete n[slot.id]; setSurvey({...survey, photos: n, score: 0}); }} className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center text-white rounded-[1.8rem] z-30"><Trash2 size={24}/></button>
                        <div className="absolute top-2 left-3 px-2 py-0.5 bg-black/60 text-white rounded-full text-[0.45rem] font-black uppercase z-20">{slot.label}</div>
                    </>
                  ) : (
                    <>
                        <Camera size={24} className="text-slate-300 mb-2 group-hover:text-primary-500 transition-colors"/>
                        <p className="text-[0.6rem] font-black uppercase text-slate-500 tracking-tight">{slot.label}</p>
                        <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => { const f = e.target.files?.[0]; if (f) handlePhotoUpload(f, slot.id, slot.label); }} />
                    </>
                  )}
                </div>
                {hasPhoto && val?.status === 'INVALID' && val.recommendation && (
                   <div className="p-2.5 bg-rose-50 dark:bg-rose-900/20 rounded-xl border border-rose-100 dark:border-rose-900/30 flex gap-2 animate-fade-in">
                      <Lightbulb size={12} className="text-rose-500 flex-shrink-0 mt-0.5"/>
                      <p className="text-[0.55rem] font-bold text-rose-800 dark:text-rose-300 leading-tight">{val.recommendation}</p>
                   </div>
                )}
              </div>
           )})}
        </div>

        {Object.keys(survey.photos).length === 5 && (
           <div className="space-y-6 pt-2 animate-pop-in">
              {loading ? (
                <div className="p-10 bg-white dark:bg-slate-900 rounded-[3rem] shadow-xl text-center space-y-6">
                   <Zap size={48} className="text-primary-500 animate-pulse mx-auto" />
                   <p className="text-sm font-bold text-slate-500">Asisten SurePath sedang mengecek kondisi mobilmu...</p>
                </div>
              ) : survey.score > 0 ? (
                <div className="p-8 bg-white dark:bg-slate-900 border-2 border-emerald-500/20 rounded-[3rem] shadow-xl space-y-6 animate-pop-in">
                   <div className="flex items-center gap-6">
                      <div className="relative w-20 h-20 flex items-center justify-center">
                         <svg className="w-full h-full transform -rotate-90">
                            <circle cx="40" cy="40" r="36" stroke="currentColor" strokeWidth="6" fill="transparent" className="text-slate-100 dark:text-slate-800"/>
                            <circle cx="40" cy="40" r="36" stroke="currentColor" strokeWidth="6" fill="transparent" strokeDasharray={226.2} strokeDashoffset={226.2 - (226.2 * survey.score) / 100} className="text-emerald-500 transition-all duration-1000"/>
                         </svg>
                         <span className="absolute text-xl font-black text-slate-900 dark:text-white">{survey.score}</span>
                      </div>
                      <div className="space-y-1">
                         <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-widest">Kondisi Mobil</p>
                         <h4 className="text-xl font-black uppercase text-emerald-600">Mobil Anda Lolos!</h4>
                         <p className="text-[0.7rem] text-slate-500 font-bold leading-tight">{survey.summary}</p>
                      </div>
                   </div>
                   <div className="flex items-center gap-3 text-emerald-600 font-black uppercase text-[0.6rem] tracking-widest">
                      <CheckCircle2 size={16}/> Selesai! Klik lanjut untuk checkout.
                   </div>
                </div>
              ) : (
                <button 
                  onClick={runSurveyAI} 
                  className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-sm shadow-xl active:scale-95 transition-all flex items-center justify-center gap-4 group"
                >
                   <Zap size={24} className="text-primary-500 group-hover:rotate-12 transition-transform"/> 
                   Verifikasi Mobil Sekarang
                </button>
              )}
           </div>
        )}
      </div>
    </PageTransition>
  );
};

