import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, Loader2, ShieldAlert, ChevronLeft, HeartPulse, Stethoscope, Sparkles } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";
import { NeuralBot, PageTransition } from './car-wizard/WizardUI';

const HealthChat = ({ onBack }: { onBack: () => void }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'model', text: string }[]>([
    { role: 'model', text: 'Halo! Saya asisten kesehatan SurePath. Ada yang bisa saya bantu hari ini? Anda bisa tanya seputar keluhan kesehatan ringan atau info asuransi kesehatan Anda.' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || loading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...messages, { role: 'user', text: userMsg }].map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        })),
        config: {
          systemInstruction: `Anda adalah SurePath Companion, asisten kesehatan AI yang sangat ramah, hangat, dan penuh empati. 
          Gaya bicara Anda seperti sahabat yang pintar.
          Tugas Anda:
          1. Memberikan info kesehatan dasar yang menenangkan.
          2. Membantu memahami istilah polis asuransi dengan bahasa yang simpel.
          3. SELALU ingatkan bahwa Anda adalah AI dan nasabah tetap harus periksa ke dokter sungguhan untuk diagnosa pasti.
          Gunakan Bahasa Indonesia yang santai tapi sopan. Hindari bahasa teknis yang terlalu kaku.`,
          temperature: 0.8,
        }
      });

      const aiText = response.text;
      setMessages(prev => [...prev, { role: 'model', text: aiText || 'Waduh, sepertinya koneksi saya lagi kurang enak nih. Bisa tanya lagi?' }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: 'Maaf ya, sistem saya lagi istirahat sebentar. Coba lagi nanti ya!' }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <PageTransition>
      <div className="flex flex-col h-full bg-white dark:bg-slate-950 transition-all duration-700">
        {/* Header Chat */}
        <div className="px-6 pt-6 pb-4 bg-white/80 dark:bg-black/40 backdrop-blur-2xl border-b border-slate-100 dark:border-white/5 flex items-center justify-between z-50">
          <div className="flex items-center gap-4">
             <button onClick={onBack} className="p-2.5 bg-slate-50 dark:bg-white/5 rounded-2xl text-slate-400 hover:text-primary-500 transition-colors">
                <ChevronLeft size={20}/>
             </button>
             <div className="flex items-center gap-3">
                <div className="w-12 h-12 bg-emerald-500 rounded-[1.2rem] flex items-center justify-center text-white shadow-lg shadow-emerald-500/20">
                   <HeartPulse size={24}/>
                </div>
                <div>
                   <h3 className="text-lg font-black uppercase tracking-tight leading-none text-slate-800 dark:text-white">Sahabat <span className="text-primary-500">Kesehatan</span></h3>
                   <p className="text-[0.6rem] font-bold text-emerald-600 uppercase tracking-widest mt-1.5 flex items-center gap-1.5">
                      <Sparkles size={10} className="fill-current"/> Siap Membantu
                   </p>
                </div>
             </div>
          </div>
        </div>

        {/* Chat Area */}
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar pb-40">
          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in`}>
              <div className={`flex gap-4 max-w-[85%] ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                <div className={`w-9 h-9 rounded-[0.8rem] flex-shrink-0 flex items-center justify-center shadow-lg ${m.role === 'user' ? 'bg-primary-500 text-white' : 'bg-emerald-500 text-white'}`}>
                  {m.role === 'user' ? <User size={18}/> : <Bot size={18}/>}
                </div>
                <div className={`p-5 rounded-[1.8rem] text-[0.95rem] leading-relaxed shadow-xl border ${
                  m.role === 'user' 
                  ? 'bg-primary-500 text-white rounded-tr-none border-primary-400' 
                  : 'bg-slate-50 dark:bg-slate-900 text-slate-800 dark:text-slate-200 border-slate-100 dark:border-white/5 rounded-tl-none'
                }`}>
                  {m.text}
                </div>
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-start animate-pulse">
               <div className="flex gap-3 items-center bg-slate-50 dark:bg-slate-900 p-4 rounded-2xl rounded-tl-none border border-slate-100 dark:border-white/5">
                  <Loader2 size={16} className="animate-spin text-primary-500"/>
                  <span className="text-[0.6rem] font-black uppercase tracking-widest text-slate-400">Sedang Mengetik...</span>
               </div>
            </div>
          )}
        </div>

        {/* Input Form */}
        <div className="p-6 bg-white/80 dark:bg-black/60 backdrop-blur-2xl border-t border-slate-100 dark:border-white/5 fixed bottom-0 left-0 right-0 z-20">
          <div className="max-w-3xl mx-auto flex gap-3 items-center">
            <div className="flex-1 relative">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Tanya apa saja..."
                className="w-full bg-slate-50 dark:bg-slate-900 border-2 border-slate-100 dark:border-white/5 rounded-[1.8rem] py-5 px-6 pr-16 text-sm font-semibold outline-none focus:border-primary-500 transition-all shadow-inner placeholder:text-slate-300 dark:text-white"
              />
              <button 
                onClick={handleSend}
                disabled={loading || !input.trim()}
                className="absolute right-2.5 top-2.5 bottom-2.5 px-5 bg-primary-500 text-white rounded-2xl shadow-xl shadow-primary-500/20 active:scale-95 transition-all disabled:opacity-30 disabled:shadow-none"
              >
                <Send size={20} strokeWidth={2.5}/>
              </button>
            </div>
          </div>
          <div className="mt-5 flex items-center justify-center gap-3 opacity-40">
             <ShieldAlert size={14} className="text-rose-500"/>
             <p className="text-[0.6rem] font-bold uppercase tracking-[0.1em] text-slate-500">Saran AI bukan diagnosa medis resmi.</p>
          </div>
        </div>
      </div>
    </PageTransition>
  );
};

