                         <div className="w-full h-full bg-gradient-to-tr from-slate-50 to-slate-100 dark:from-slate-800 dark:to-slate-900 flex items-center justify-center text-3xl font-black text-slate-300 dark:text-slate-700">
                           {currentUser?.name?.[0]}
                         </div>
                      </div>
