const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);

  const messages = [
    "Menyapa Anda...",
    "Menyiapkan proteksi terbaik...",
    "Mengecek penawaran spesial...",
    "Sistem siap melayani...",
    "Mari melangkah bersama!"
  ];

  useEffect(() => {
    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 2.5)), 40);
    const msgTimer = setInterval(() => setMessageIdx(i => (i < messages.length - 1 ? i + 1 : i)), 700);
    const finishTimer = setTimeout(onFinish, 3000);
    return () => { clearInterval(timer); clearInterval(msgTimer); clearTimeout(finishTimer); };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[5000] bg-white dark:bg-slate-950 flex flex-col items-center justify-center overflow-hidden transition-colors duration-700">
      <div className="relative z-10 flex flex-col items-center animate-pop-in">
        <div className="mb-12 relative group">
           <div className="absolute inset-0 bg-primary-500/10 rounded-full blur-[80px] animate-pulse scale-150"></div>
           <NeuralBot className="w-44 h-44 relative" mood="happy" />
        </div>
        <div className="text-center space-y-6">
          <h1 className="text-4xl font-black tracking-tight text-slate-900 dark:text-white uppercase leading-none">
            SURE<span className="text-primary-500">PATH</span>
