import React, { useState, useEffect } from 'react';
import { 
  User, Lock, Eye, EyeOff, ArrowRight, 
  Globe, Radio, ShieldAlert, Fingerprint, Sparkles, Activity,
  BellRing, X, RefreshCw, Smartphone, BadgeCheck, KeyRound, Briefcase, 
  Zap, ChevronRight, LayoutDashboard, Wallet, Building2, UserCircle,
  AlertCircle, Monitor, Heart, ArrowLeft
} from 'lucide-react';
import { SurePathLogo } from './Navbar';
import { Language, UserRole } from '../types';
import { db, seedDatabase, User as DBUser } from '../db';
import { hashPassword, verifyPassword } from '../services/authService';
import { NeuralBot } from './car-wizard/WizardUI';

interface AuthGateProps {
  onAuthSuccess: (user: any) => void;
  initialLang?: Language;
  onBackToWebsite?: () => void;
}

const InputField = ({ icon: Icon, label, type, value, onChange, showPass, setShowPass, placeholder }: any) => (
  <div className="space-y-1.5 group animate-fade-in">
    <label className="text-xs font-bold text-slate-400 dark:text-slate-500 ml-1 group-focus-within:text-primary-500 transition-colors">
      {label}
    </label>
    <div className="relative">
      <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-primary-500 transition-all">
        <Icon size={18} />
      </div>
      <input 
        type={type === 'password' && showPass ? 'text' : type}
        placeholder={placeholder}
        required
        className="w-full pl-12 pr-12 py-4 bg-slate-50 dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-2xl outline-none transition-all font-semibold text-sm text-slate-900 dark:text-white placeholder:text-slate-300 focus:border-primary-500 focus:bg-white dark:focus:bg-black shadow-sm"
        value={value}
        onChange={(e) => onChange(e.target.value)}
      />
      {type === 'password' && (
        <button 
          type="button"
          onClick={() => setShowPass(!showPass)}
          className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 hover:text-primary-500 p-2"
        >
          {showPass ? <EyeOff size={18}/> : <Eye size={18}/>}
        </button>
      )}
    </div>
  </div>
);

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.ID, onBackToWebsite }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY' | 'DEMO_SELECT'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingOtp, setShowIncomingOtp] = useState(false);
  const [statusMsg, setStatusMsg] = useState('Selamat Datang');

  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });

  useEffect(() => {
    seedDatabase();
  }, []);

  const handleQuickDemo = async (email: string, role: UserRole) => {
    setLoading(true);
    setStatusMsg('Menyiapkan akun demo...');
    try {
      const user = await db.users.where('email').equals(email).first();
      if (user) {
        setTimeout(() => onAuthSuccess(user), 1000);
      } else {
        setError("Akun demo tidak ditemukan.");
        setLoading(false);
      }
    } catch (err) {
      setError("Gagal tersambung.");
      setLoading(false);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setStatusMsg('Memproses data...');

    try {
      if (mode === 'LOGIN') {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            setStatusMsg('Identitas terverifikasi!');
            setTimeout(() => onAuthSuccess(user), 800);
          } else {
            setError("Email atau kata sandi salah.");
            setLoading(false);
          }
        } else {
          setError("Akun belum terdaftar.");
          setLoading(false);
        }
      } else {
        const existing = await db.users.where('email').equals(formData.email).first();
        if (existing) {
          setError("Email sudah digunakan.");
          setLoading(false);
          return;
        }
        const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedOtp(newOtp);
        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
          setShowIncomingOtp(true);
          setStatusMsg('Kode verifikasi dikirim!');
        }, 1200);
      }
    } catch (err) {
      setError("Gangguan sistem sementara.");
      setLoading(false);
    }
  };

  const finalizeRegistration = async () => {
    setLoading(true);
    setStatusMsg('Menyimpan data Anda...');
    try {
      const { hash, salt } = await hashPassword(formData.password);
      const newUser: DBUser = {
        name: formData.name, email: formData.email, phone: formData.phone,
        passwordHash: hash, salt: salt, role: UserRole.CUSTOMER,
        nodeId: `SP-USER-${Math.floor(1000 + Math.random() * 9000)}`,
        verified: true, trustScore: 85, memberSince: new Date().toISOString()
      };
      const id = await db.users.add(newUser);
      onAuthSuccess({ ...newUser, id });
    } catch (err) {
      setError("Gagal mendaftar.");
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex flex-col items-center p-6 relative overflow-hidden transition-colors duration-700">

      <div className="absolute top-[-5%] right-[-10%] w-[400px] h-[400px] bg-primary-500/10 rounded-full blur-[100px] pointer-events-none"></div>

      {showIncomingOtp && (
        <div className="fixed top-8 left-8 right-8 z-[300] animate-pop-in">
           <div className="bg-slate-900/95 backdrop-blur-2xl rounded-3xl p-6 shadow-2xl flex items-center gap-6 border border-white/10">
              <div className="w-14 h-14 bg-primary-500 rounded-2xl flex items-center justify-center text-white shadow-lg"><BellRing size={28}/></div>
              <div className="flex-1">
                 <p className="text-[0.6rem] font-black text-primary-400 uppercase tracking-widest mb-1">Pesan Masuk</p>
                 <div className="flex items-center gap-4">
                    <span className="text-3xl font-black text-white tracking-[0.3em] font-mono">{generatedOtp}</span>
                    <button onClick={() => { setOtp(generatedOtp); setShowIncomingOtp(false); }} className="ml-auto px-6 py-2 bg-primary-500 text-white rounded-xl text-xs font-black">SALIN</button>
                 </div>
              </div>
           </div>
        </div>
      )}

      <div className="w-full flex items-center justify-between mb-8 z-50">
        <button onClick={onBackToWebsite} className="flex items-center gap-2 px-4 py-2 bg-white/50 dark:bg-black/50 rounded-full border border-slate-100 dark:border-white/5 text-[0.65rem] font-black text-slate-500 uppercase tracking-widest hover:text-primary-500 transition-colors">
            <ArrowLeft size={14}/> Kembali
        </button>
        <div className="flex items-center gap-3 bg-white/50 dark:bg-black/50 px-4 py-2 rounded-full border border-slate-100 dark:border-white/5 backdrop-blur-md">
          <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
          <p className="text-[0.65rem] font-black text-slate-500 uppercase tracking-[0.2em]">{statusMsg}</p>
        </div>
      </div>

      <div className="w-full max-w-md flex flex-col items-center space-y-8 flex-1 relative z-10">
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-6">
            <div className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-white/5 relative group">
               <SurePathLogo className="w-20 h-20 relative z-10 group-hover:scale-105 transition-transform" />
            </div>
            <div className="absolute -bottom-3 -right-3 w-12 h-12">
               <NeuralBot mood={loading ? 'thinking' : 'happy'} className="w-full h-full" color="primary" />
            </div>
          </div>
          <h1 className="text-3xl font-black tracking-tight uppercase text-slate-900 dark:text-white leading-none">Sure<span className="text-primary-500">Path</span></h1>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.4em] mt-3">Portal Dashboard Pintar</p>
        </div>

        <div className="w-full bg-white dark:bg-slate-900 rounded-[3rem] p-8 shadow-2xl border border-slate-100 dark:border-white/5 overflow-hidden">
          {mode === 'DEMO_SELECT' ? (
            <div className="space-y-6 animate-pop-in">
               <div className="flex items-center justify-between mb-2">
                  <h3 className="font-bold uppercase tracking-tight text-sm text-slate-400">Pilih Demo Dashboard</h3>
                  <button onClick={() => setMode('LOGIN')} className="p-2 hover:bg-slate-50 dark:hover:bg-white/10 rounded-xl transition-all text-slate-400"><X size={20}/></button>
               </div>
               <div className="space-y-4">
                 <button onClick={() => handleQuickDemo('user@surepath.ai', UserRole.CUSTOMER)} className="w-full p-6 bg-blue-50/50 dark:bg-blue-500/10 rounded-[2rem] border border-blue-100 dark:border-blue-500/20 text-left flex items-center gap-5 group hover:border-blue-500 transition-all">
                    <div className="w-12 h-12 bg-blue-500 rounded-2xl flex items-center justify-center text-white shadow-lg group-hover:scale-110 transition-transform"><LayoutDashboard size={24}/></div>
                    <div><p className="font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Nasabah (Ada Polis)</p><p className="text-[0.65rem] text-blue-600 font-bold uppercase mt-1 tracking-widest">Lihat Dashboard Full</p></div>
                 </button>
                 <button onClick={() => handleQuickDemo('agent@surepath.ai', UserRole.AGENT)} className="w-full p-6 bg-emerald-50/50 dark:bg-emerald-500/10 rounded-[2rem] border border-emerald-100 dark:border-emerald-500/20 text-left flex items-center gap-5 group hover:border-emerald-500 transition-all">
                    <div className="w-12 h-12 bg-emerald-500 rounded-2xl flex items-center justify-center text-white shadow-lg group-hover:scale-110 transition-transform"><Briefcase size={24}/></div>
                    <div><p className="font-black text-slate-900 dark:text-white uppercase text-sm tracking-tight">Simulasi Sebagai Agen</p><p className="text-[0.65rem] text-emerald-600 font-bold uppercase mt-1 tracking-widest">Kelola Jaringan</p></div>
                 </button>
               </div>
            </div>
          ) : mode === 'VERIFY' ? (
            <div className="space-y-8 text-center animate-pop-in py-4">
              <div className="space-y-2">
                <h3 className="text-xl font-black uppercase tracking-tight">Cek Kode Anda</h3>
                <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Masukkan 6 digit kode keamanan.</p>
              </div>
              <input 
                type="tel" maxLength={6} placeholder="000000"
                className="w-full bg-transparent border-b-2 border-slate-200 dark:border-white/10 text-center text-4xl font-black tracking-[0.4em] text-primary-500 outline-none focus:border-primary-500 transition-all"
                value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
              />
              <button 
                onClick={async () => otp === generatedOtp ? await finalizeRegistration() : setError("Kode salah.")} 
                disabled={otp.length < 6 || loading} 
                className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-3xl font-black uppercase text-xs tracking-[0.2em] shadow-xl active:scale-95 disabled:opacity-30"
              >
                Konfirmasi
              </button>
            </div>
          ) : (
            <form onSubmit={handleAuth} className="space-y-6">
              <div className="flex bg-slate-50 dark:bg-white/[0.05] p-1.5 rounded-2xl mb-2 border border-slate-100 dark:border-white/5">
                <button type="button" onClick={() => setMode('LOGIN')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${mode === 'LOGIN' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-400 opacity-60'}`}>Masuk</button>
                <button type="button" onClick={() => setMode('REGISTER')} className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${mode === 'REGISTER' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-400 opacity-60'}`}>Daftar</button>
              </div>

              <div className="space-y-5">
                {mode === 'REGISTER' && (
                  <InputField icon={User} label="Nama Lengkap" value={formData.name} onChange={(v:any)=>setFormData({...formData, name: v})} placeholder="Contoh: John Doe" />
                )}
                <InputField icon={Globe} label="Alamat Email" type="email" value={formData.email} onChange={(v:any)=>setFormData({...formData, email: v})} placeholder="email@contoh.com" />
                <InputField icon={KeyRound} label="Kata Sandi" type="password" value={formData.password} onChange={(v:any)=>setFormData({...formData, password: v})} showPass={showPass} setShowPass={setShowPass} placeholder="••••••••" />
              </div>

              {error && <div className="p-4 bg-rose-50 dark:bg-rose-500/10 border border-rose-100 dark:border-rose-500/20 rounded-2xl text-rose-500 text-[0.7rem] font-black text-center uppercase tracking-widest">{error}</div>}

              <div className="space-y-4 pt-2">
                <button type="submit" disabled={loading} className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-3xl font-black uppercase text-xs tracking-[0.2em] shadow-xl hover:shadow-primary-500/10 active:scale-95 transition-all flex items-center justify-center gap-3 group">
                   {loading ? <RefreshCw size={18} className="animate-spin text-primary-500"/> : (mode === 'LOGIN' ? 'Masuk Sekarang' : 'Lanjutkan')} 
                   {!loading && <ArrowRight size={18} className="text-primary-500 group-hover:translate-x-1 transition-transform"/>}
                </button>

                <button type="button" onClick={() => setMode('DEMO_SELECT')} className="w-full py-5 bg-white dark:bg-slate-800 text-slate-500 dark:text-slate-400 border-2 border-slate-100 dark:border-white/5 rounded-3xl font-black uppercase text-[0.65rem] tracking-[0.2em] hover:bg-slate-50 transition-all flex items-center justify-center gap-3">
                  <Sparkles size={14} className="text-amber-500 fill-amber-500"/> Akses Demo Dashboard
                </button>
              </div>
            </form>
          )}
        </div>

        <div className="flex items-center gap-8 opacity-30 py-6">
           <div className="flex items-center gap-2"><BadgeCheck size={16} className="text-primary-500"/><span className="text-[0.6rem] font-black uppercase tracking-widest leading-none">OJK Terverifikasi</span></div>
           <div className="flex items-center gap-2"><Smartphone size={16} className="text-blue-500"/><span className="text-[0.6rem] font-black uppercase tracking-widest leading-none">Aman & Nyaman</span></div>
        </div>
      </div>
    </div>
  );
};

