const INITIAL_PRODUCTS = [
  { id: 'car', title: 'Asuransi Mobil', label: 'Asuransi Mobil', icon: Car, color: 'text-blue-500', active: true, cat: 'Retail', tech: 'AI Foto Kerusakan' },
  { id: 'travel', title: 'Asuransi Perjalanan', label: 'Asuransi Perjalanan', icon: Plane, color: 'text-emerald-500', active: true, cat: 'Retail', tech: 'Otomatis & Cepat' },
  { id: 'pa', title: 'Kecelakaan Diri', label: 'Kecelakaan Diri', icon: ShieldAlert, color: 'text-rose-500', active: true, cat: 'Retail', tech: 'Proteksi Penuh' },
  { id: 'mpar', title: 'Proteksi Barang', label: 'Proteksi Barang', icon: Package, color: 'text-amber-500', active: true, cat: 'Retail', tech: 'Peralatan & Gadget' },
];

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [products] = useState(INITIAL_PRODUCTS);
  const [lang, setLang] = useState<Language>(Language.ID);
  const [latestPolicy, setLatestPolicy] = useState<Policy | null>(null);

  const timeGreeting = useMemo(() => {
    const hour = new Date().getHours();
    if (hour < 11) return "Selamat Pagi";
    if (hour < 15) return "Selamat Siang";
    if (hour < 19) return "Selamat Sore";
    return "Selamat Malam";
  }, []);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
        db.policies.where('userId').equals(user.id).toArray().then(res => {
           if (res.length > 0) setLatestPolicy(res.sort((a,b) => b.id! - a.id!)[0]);
        });
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, [currentPage]);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleDemoLogin = async () => {
    const user = await db.users.where('email').equals('user@surepath.ai').first();
    if (user) handleAuthSuccess(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  const handleEnterPortal = () => {
    setAppMode(true);
    setPage('auth');
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  if (currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE, UserRole.INSURANCE_ADMIN].includes(currentUser.role)) {
    return <AdminPortal onLogout={handleLogout} products={products} setProducts={() => {}} userRole={currentUser.role} />;
  }

  // Determine if we should show the landing page or the app/auth screen
  const showLanding = !isMobile && !appMode && !currentUser && currentPage !== 'auth';

  if (showLanding) {
    return (
      <div className={darkMode ? 'dark' : ''}>
        <Navbar 
            lang={lang} 
            setLang={setLang} 
            darkMode={darkMode} 
            setDarkMode={setDarkMode} 
            currentPage={currentPage} 
            setPage={(p) => p === 'auth' ? handleEnterPortal() : setPage(p)} 
            onDemoLogin={handleDemoLogin}
        />
        <DesktopWebsite 
            onEnterPortal={handleEnterPortal} 
            onAdminAccess={handleEnterPortal} 
            currentLang={lang} 
            onLangChange={setLang} 
        />
      </div>
    );
  }

  // If we are in "App Mode" or "Mobile" or "User is logged in" or "Page is auth", show AuthGate if no user
  if (!currentUser) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} onBackToWebsite={() => setAppMode(false)} />;
  }

  const renderPortalContent = () => {
    switch(currentPage) {
      case 'home':
        return <PortalDashboard currentUser={currentUser} setPage={setPage} lang={lang} />;
      case 'products':
        return (
          <PageTransition>
            <div className="space-y-8 pb-24 pt-2">
              <h2 className="text-4xl font-black uppercase tracking-tighter px-2 text-slate-900 dark:text-white leading-none">Pilihan <span className="text-primary-500">Proteksi</span></h2>
              <div className="grid gap-4">
                {products.map(p => (
                  <div key={p.id} onClick={() => setPage(`buy-${p.id}`)} className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 flex items-center justify-between active:scale-[0.98] transition-all duration-500 cursor-pointer shadow-lg hover:border-primary-500/30 hover:scale-[1.01] hover:shadow-2xl group">
                    <div className="flex items-center gap-6">
                      <div className={`w-16 h-16 bg-gray-50 dark:bg-white/5 ${p.color} rounded-2xl flex items-center justify-center shadow-inner group-hover:scale-110 transition-transform`}><p.icon size={32} strokeWidth={2.5}/></div>
                      <div>
                        <h4 className="font-black text-xl uppercase text-slate-900 dark:text-white leading-none mb-2">{p.title}</h4>
                        <p className="text-[0.65rem] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-[0.2em]">{p.tech}</p>
                      </div>
                    </div>
                    <div className="w-12 h-12 rounded-full border border-slate-100 dark:border-white/10 flex items-center justify-center group-hover:bg-primary-500 group-hover:text-white group-hover:border-primary-500 transition-all"><ChevronRight size={24}/></div>
                  </div>
                ))}
              </div>
            </div>
          </PageTransition>
        );
      case 'claim': return <PageTransition><ClaimManager onComplete={() => setPage('home')} /></PageTransition>;
      case 'wallet': return <PageTransition><AgentsWallet /></PageTransition>;
      case 'profile': return <PageTransition><UserProfile currentUser={currentUser} onStartClaim={() => setPage('claim')} /></PageTransition>;
      case 'buy-car': return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-travel': return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-pa': return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-mpar': return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'bot': return <HealthChat onBack={() => setPage('home')} />;
      default: return null;
    }
  };

  const isWizardFlow = currentPage.startsWith('buy-');
  const navItems = [
    { id: 'home', icon: HomeIcon, label: 'Beranda' },
    { id: 'products', icon: ShoppingBag, label: 'Produk' }, 
    { id: 'bot', icon: Bot, label: 'Tanya AI' },
    { id: 'claim', icon: Zap, label: 'Klaim' },
    { id: 'profile', icon: UserCircle, label: 'Akun' }
  ];

  return (
    <div className={`${darkMode ? 'dark bg-[#0a0a0a]' : 'bg-[#fafaf9]'} h-full transition-all duration-700 font-sans flex flex-col relative overflow-hidden`}>
      {!isWizardFlow && (
        <header className="flex-shrink-0 h-24 glass-card px-8 flex items-center justify-between border-b border-slate-200/50 dark:border-white/5 z-[60] relative bg-white/80 dark:bg-black/20 backdrop-blur-xl transition-all duration-700">
          <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setPage('home')}>
            <SurePathLogo className="w-12 h-12 group-hover:scale-110 transition-transform" />
            <div className="flex flex-col">
              <span className="font-black text-2xl tracking-tighter uppercase leading-none text-slate-900 dark:text-white">Sure<span className="text-primary-500">Path</span></span>
              <span className="text-[0.45rem] font-bold text-slate-400 dark:text-slate-600 uppercase tracking-[0.5em] mt-1.5 transition-colors duration-700">{currentUser?.name || 'Halo!'}</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setDarkMode(!darkMode)} className="p-3.5 bg-white dark:bg-slate-800 rounded-2xl text-slate-400 dark:text-slate-600 hover:text-primary-500 transition-all duration-700 shadow-xl border border-slate-100 dark:border-white/5 active:rotate-45">
              {darkMode ? <Sun size={20} className="text-yellow-400"/> : <Moon size={20}/>}
            </button>
            <button onClick={handleLogout} className="p-3.5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl hover:bg-rose-500 dark:hover:bg-rose-500 transition-all duration-700 shadow-xl active:scale-95 group">
               <LogOut size={20} className="group-hover:-translate-x-0.5 transition-transform"/>
            </button>
          </div>
        </header>
      )}

      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative transition-all duration-700 ${isWizardFlow ? 'p-0 h-screen' : 'px-6 py-10'} bg-gradient-to-b from-transparent to-slate-50/40 dark:to-slate-950/20`}>
        {renderPortalContent()}
      </main>

      {!isWizardFlow && (
        <nav className="flex-shrink-0 fixed bottom-8 inset-x-6 h-22 bg-white/90 dark:bg-[#111]/90 backdrop-blur-2xl z-[70] flex items-center justify-around px-6 rounded-[3rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.15)] border border-slate-200/50 dark:border-white/10 max-w-xl mx-auto transition-all duration-700">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-2 flex-1 py-4 transition-all duration-500 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-primary-500 scale-110 -translate-y-1' : 'text-slate-400 dark:text-slate-600'}`}>
              <item.icon size={26} strokeWidth={currentPage === item.id ? 2.5 : 2} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(249,115,22,0.5)]' : ''} />
              <span className={`text-[0.5rem] font-black uppercase tracking-[0.2em] ${currentPage === item.id ? 'opacity-100' : 'opacity-60'}`}>{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );
};

export default App;

