const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 4)), 30);
    const finishTimer = setTimeout(onFinish, 2000);
    return () => { clearInterval(timer); clearTimeout(finishTimer); };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[5000] bg-[#fafaf9] flex flex-col items-center justify-center">
      <div className="relative flex flex-col items-center animate-pop-in">
        <SurePathLogo className="w-24 h-24 mb-10" />
        <div className="text-center space-y-6">
          <h1 className="text-3xl font-black tracking-tight text-slate-900 uppercase">
            SURE<span className="text-primary-500">PATH</span>
          </h1>
          <div className="w-48 h-1.5 bg-slate-100 rounded-full overflow-hidden">
              <div className="h-full bg-primary-500 transition-all duration-300" style={{ width: `${progress}%` }}></div>
          </div>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-widest">Menyiapkan Pengalaman Terbaik...</p>
        </div>
      </div>
    </div>
  );
};

const INITIAL_PRODUCTS = [
  { id: 'car', title: 'Asuransi Mobil', label: 'Mobil Aman', icon: Car, color: 'text-blue-500', active: true, cat: 'Retail', tech: 'Proteksi lengkap untuk mobil kesayangan.' },
  { id: 'travel', title: 'Asuransi Perjalanan', label: 'Travel Tenang', icon: Plane, color: 'text-emerald-500', active: true, cat: 'Retail', tech: 'Jalan-jalan tanpa rasa khawatir.' },
  { id: 'pa', title: 'Kecelakaan Diri', label: 'Diri Terjaga', icon: ShieldAlert, color: 'text-rose-500', active: true, cat: 'Retail', tech: 'Santunan cepat saat terjadi musibah.' },
  { id: 'mpar', title: 'Proteksi Barang', label: 'Barang Awet', icon: Package, color: 'text-amber-500', active: true, cat: 'Retail', tech: 'Lindungi gadget & barang elektronikmu.' },
];

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [products] = useState(INITIAL_PRODUCTS);
  const [lang, setLang] = useState<Language>(Language.ID);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, []);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleLogout = () => {
    if (confirm("Ingin keluar dari aplikasi?")) {
      setCurrentUser(null);
      localStorage.removeItem('SUREPATH_SESSION');
      setAppMode(false);
      setPage('home');
    }
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  if (currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE, UserRole.INSURANCE_ADMIN].includes(currentUser.role)) {
    return <AdminPortal onLogout={handleLogout} products={products} setProducts={() => {}} userRole={currentUser.role} />;
  }

  if (!isMobile && !appMode && !currentUser && currentPage !== 'auth') {
    return (
      <div className={darkMode ? 'dark' : ''}>
        <Navbar lang={lang} setLang={setLang} darkMode={darkMode} setDarkMode={setDarkMode} currentPage={currentPage} setPage={(p) => p === 'auth' ? handleAuthSuccess : setPage(p)} />
        <DesktopWebsite onEnterPortal={() => { setAppMode(true); setPage('auth'); }} onAdminAccess={() => { setAppMode(true); setPage('auth'); }} currentLang={lang} onLangChange={setLang} />
      </div>
    );
  }

  if (!currentUser) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} onBackToWebsite={() => setAppMode(false)} />;
  }

  const renderPortalContent = () => {
    switch(currentPage) {
      case 'home': return <PortalDashboard currentUser={currentUser} setPage={setPage} lang={lang} />;
      case 'products':
        return (
          <PageTransition>
            <div className="space-y-8 pb-32 pt-4">
              <h2 className="text-3xl font-black tracking-tighter px-2">Pilihan <span className="text-primary-500">Proteksi</span></h2>
              <div className="grid gap-4">
                {products.map(p => (
                  <div key={p.id} onClick={() => setPage(`buy-${p.id}`)} className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] friendly-shadow flex items-center justify-between active:scale-[0.98] transition-all duration-300 cursor-pointer group">
                    <div className="flex items-center gap-6">
                      <div className={`w-14 h-14 bg-slate-50 dark:bg-white/5 ${p.color} rounded-2xl flex items-center justify-center shadow-inner group-hover:scale-110 transition-transform`}><p.icon size={28} /></div>
                      <div>
                        <h4 className="font-bold text-lg text-slate-900 dark:text-white leading-none mb-1.5">{p.title}</h4>
                        <p className="text-[0.7rem] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest">{p.label}</p>
                      </div>
                    </div>
                    <ChevronRight size={20} className="text-slate-300"/>
                  </div>
                ))}
              </div>
            </div>
          </PageTransition>
        );
      case 'claim': return <PageTransition><ClaimManager onComplete={() => setPage('home')} /></PageTransition>;
      case 'wallet': return <PageTransition><AgentsWallet /></PageTransition>;
      case 'profile': return <PageTransition><UserProfile currentUser={currentUser} /></PageTransition>;
      case 'buy-car': return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-travel': return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-pa': return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-mpar': return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'bot': return <HealthChat onBack={() => setPage('home')} />;
      default: return null;
    }
  };

  const isWizardFlow = currentPage.startsWith('buy-');
  const navItems = [
    { id: 'home', icon: HomeIcon, label: 'Awal' },
    { id: 'products', icon: ShoppingBag, label: 'Produk' }, 
    { id: 'bot', icon: Bot, label: 'Pathy' },
    { id: 'claim', icon: Zap, label: 'Lapor' },
    { id: 'profile', icon: UserCircle, label: 'Saya' }
  ];

  return (
    <div className={`${darkMode ? 'dark bg-[#0c0a09]' : 'bg-[#fafaf9]'} h-full transition-all duration-500 font-sans flex flex-col relative overflow-hidden`}>
      {!isWizardFlow && (
        <header className="flex-shrink-0 h-24 px-8 flex items-center justify-between border-b border-slate-100 dark:border-white/5 z-[60] bg-white/80 dark:bg-black/20 backdrop-blur-xl">
          <div className="flex items-center gap-4 cursor-pointer" onClick={() => setPage('home')}>
            <SurePathLogo className="w-10 h-10" />
            <div className="flex flex-col">
              <span className="font-bold text-xl uppercase leading-none text-slate-900 dark:text-white">Sure<span className="text-primary-500">Path</span></span>
              <span className="text-[0.45rem] font-bold text-slate-400 uppercase tracking-[0.4em] mt-1">{currentUser?.name.split(' ')[0]} Node</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-white dark:bg-slate-800 rounded-2xl text-slate-400 hover:text-primary-500 transition-all shadow-lg border border-slate-50 dark:border-white/5">
              {darkMode ? <Sun size={20} /> : <Moon size={20} />}
            </button>
            <button onClick={handleLogout} className="p-3 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl hover:bg-rose-500 transition-all shadow-lg active:scale-90">
               <LogOut size={20} />
            </button>
          </div>
        </header>
      )}

      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative ${isWizardFlow ? 'p-0 h-screen' : 'px-6 py-6'}`}>
        {renderPortalContent()}
      </main>

      {!isWizardFlow && (
        <nav className="flex-shrink-0 fixed bottom-8 inset-x-6 h-22 bg-white/90 dark:bg-[#111]/90 backdrop-blur-2xl z-[70] flex items-center justify-around px-4 rounded-[2.8rem] friendly-shadow border border-slate-100 dark:border-white/10 max-w-xl mx-auto transition-all duration-500">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-1.5 flex-1 py-4 transition-all duration-300 tap-feedback ${currentPage === item.id ? 'text-primary-500 scale-110' : 'text-slate-400'}`}>
              <item.icon size={26} strokeWidth={currentPage === item.id ? 3 : 2} />
              <span className={`text-[0.55rem] font-bold uppercase tracking-widest ${currentPage === item.id ? 'opacity-100' : 'opacity-60'}`}>{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );
};

export default App;

