const ContextualCard = ({ title, sub, icon: Icon, color, onClick, variant = "default" }: any) => {
  const themes: any = {
    default: "bg-white dark:bg-slate-900 border-black/5 dark:border-white/5",
    active: "bg-slate-900 dark:bg-white text-white dark:text-slate-900 border-slate-800",
    success: "bg-emerald-500/10 border-emerald-500/20 text-emerald-600 dark:text-emerald-400",
  };

  return (
    <button 
      onClick={onClick}
      className={`p-6 rounded-[2.5rem] border text-left transition-all duration-300 tap-feedback flex flex-col justify-between group h-full shadow-sm hover:shadow-xl ${themes[variant]}`}
    >
      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center mb-6 shadow-inner ${color}`}>
        <Icon size={24} />
      </div>
      <div>
        <p className={`text-[0.6rem] font-bold uppercase tracking-[0.2em] mb-1 opacity-60`}>{sub}</p>
        <h4 className="text-xl font-black uppercase tracking-tighter leading-none">{title}</h4>
      </div>
    </button>
  );
};

