              <div className="h-full bg-primary-500 transition-all duration-300 shadow-[0_0_15px_#f97316]" style={{ width: `${progress}%` }}></div>
          </div>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.4em]">Sedang Menyiapkan...</p>
        </div>
      </div>
    </div>
  );
