const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 8)), 30);
    const finishTimer = setTimeout(onFinish, 1200);
    return () => { clearInterval(timer); clearTimeout(finishTimer); };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[5000] bg-[#fafaf9] flex flex-col items-center justify-center">
      <div className="relative flex flex-col items-center animate-pop-in">
        <SurePathLogo className="w-24 h-24 mb-10" />
        <div className="text-center space-y-6">
          <h1 className="text-4xl font-black tracking-tighter text-slate-900 uppercase">
            SURE<span className="text-green-600">PATH</span>
          </h1>
          <div className="w-48 h-1.5 bg-slate-100 rounded-full overflow-hidden">
              <div className="h-full bg-green-600 transition-all duration-300 shadow-[0_0_15px_#22c55e]" style={{ width: `${progress}%` }}></div>
          </div>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.4em]">Menyiapkan Dunia Anda...</p>
        </div>
      </div>
    </div>
  );
};

const INITIAL_PRODUCTS = [
  { id: 'car', title: 'Asuransi Mobil', label: 'Mobil Aman', icon: Car, color: 'text-blue-500', active: true, cat: 'Retail', tech: 'Cukup Ambil Foto' },
  { id: 'travel', title: 'Asuransi Perjalanan', label: 'Liburan Tenang', icon: Plane, color: 'text-green-600', active: true, cat: 'Retail', tech: 'Proteksi Perjalanan' },
  { id: 'pa', title: 'Kecelakaan Diri', label: 'Diri Terjaga', icon: ShieldAlert, color: 'text-rose-500', active: true, cat: 'Retail', tech: 'Bantuan Biaya Medis' },
  { id: 'mpar', title: 'Proteksi Barang', label: 'Barang Awet', icon: Package, color: 'text-amber-500', active: true, cat: 'Retail', tech: 'Asuransi Gadget & HP' },
];

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [products] = useState(INITIAL_PRODUCTS);
  const [lang, setLang] = useState<Language>(Language.ID);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, []);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleLogout = () => {
    if (confirm("Keluar dari simpul aman Anda?")) {
      setCurrentUser(null);
      localStorage.removeItem('SUREPATH_SESSION');
      setAppMode(false);
      setPage('home');
    }
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  if (currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE, UserRole.INSURANCE_ADMIN].includes(currentUser.role)) {
    return <AdminPortal onLogout={handleLogout} products={products} setProducts={() => {}} userRole={currentUser.role} />;
  }

  if (!isMobile && !appMode && !currentUser && currentPage !== 'auth') {
    return (
      <div className={darkMode ? 'dark' : ''}>
        <Navbar lang={lang} setLang={setLang} darkMode={darkMode} setDarkMode={setDarkMode} currentPage={currentPage} setPage={setPage} />
        <DesktopWebsite 
          onEnterPortal={() => { setAppMode(true); setPage('auth'); }} 
          onAdminAccess={() => { setAppMode(true); setPage('auth'); }} 
          currentLang={lang} 
          onLangChange={setLang} 
        />
      </div>
    );
  }

  if (!currentUser && (currentPage === 'auth' || appMode)) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} />;
  }

  const renderPortalContent = () => {
    switch(currentPage) {
      case 'home': return <PortalDashboard currentUser={currentUser} setPage={setPage} lang={lang} />;
      case 'products':
        return (
          <PageTransition>
            <div className="space-y-8 pb-32 pt-4 max-w-2xl mx-auto px-2">
              <h2 className="text-4xl font-black tracking-tighter">Pilih <span className="text-green-600">Perlindungan</span></h2>
              <div className="grid gap-4">
                {products.map(p => (
                  <div key={p.id} onClick={() => setPage(`buy-${p.id}`)} className="p-7 bg-white dark:bg-slate-900 rounded-[2.8rem] border border-slate-100 shadow-sm flex items-center justify-between active:scale-[0.98] transition-all duration-300 cursor-pointer group hover:shadow-xl">
                    <div className="flex items-center gap-6">
                      <div className={`w-16 h-16 bg-slate-50 dark:bg-white/5 ${p.color} rounded-2xl flex items-center justify-center shadow-inner group-hover:scale-110 transition-transform`}><p.icon size={32} /></div>
                      <div>
                        <h4 className="font-extrabold text-xl text-slate-900 dark:text-white leading-none mb-2">{p.title}</h4>
                        <p className="text-[0.7rem] text-slate-400 dark:text-slate-500 font-bold uppercase tracking-widest">{p.tech}</p>
                      </div>
                    </div>
                    <div className="w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center text-slate-300 group-hover:text-green-600 group-hover:bg-green-600/10 transition-all">
                       <ChevronRight size={24}/>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </PageTransition>
        );
      case 'claim': return <PageTransition><div className="max-w-2xl mx-auto"><ClaimManager onComplete={() => setPage('home')} /></div></PageTransition>;
      case 'wallet': return <PageTransition><div className="max-w-2xl mx-auto"><AgentsWallet /></div></PageTransition>;
      case 'profile': return <PageTransition><div className="max-w-2xl mx-auto"><UserProfile currentUser={currentUser} /></div></PageTransition>;
      case 'buy-car': return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-travel': return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-pa': return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-mpar': return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'bot': return <HealthChat onBack={() => setPage('home')} />;
      default: return <PortalDashboard currentUser={currentUser} setPage={setPage} lang={lang} />;
    }
  };

  const isWizardFlow = currentPage.startsWith('buy-');

  // Simplified Navigation Labels
  const navItems = [
    { id: 'home', icon: HomeIcon, label: 'Rumah' },
    { id: 'products', icon: ShoppingBag, label: 'Beli' }, 
    { id: 'bot', icon: Bot, label: 'Tanya' },
    { id: 'claim', icon: Zap, label: 'Bantuan' },
    { id: 'profile', icon: UserCircle, label: 'Saya' }
  ];

  return (
    <div className={`${darkMode ? 'dark bg-[#0a0a0a]' : 'bg-[#fafaf9]'} h-full min-h-screen transition-all duration-500 font-sans flex flex-col relative overflow-hidden`}>
      {!isWizardFlow && (
        <header className="flex-shrink-0 h-20 px-8 flex items-center justify-between z-[60] bg-white/80 dark:bg-black/20 backdrop-blur-xl border-b border-slate-100 dark:border-white/10">
          <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setPage('home')}>
            <SurePathLogo className="w-10 h-10 group-hover:scale-110 transition-transform" />
            <div className="flex flex-col">
              <span className="font-black text-xl uppercase tracking-tighter leading-none text-slate-900 dark:text-white">Sure<span className="text-green-600">Path</span></span>
              <span className="text-[0.45rem] font-bold text-slate-400 uppercase tracking-[0.4em] mt-1.5 transition-colors duration-700">{currentUser?.name?.split(' ')[0] || 'Tamu'} Simpul</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-white dark:bg-slate-800 rounded-2xl text-slate-400 hover:text-green-600 transition-all shadow-sm border border-slate-100 dark:border-white/10">
              {darkMode ? <Sun size={18} /> : <Moon size={18} />}
            </button>
            <button onClick={handleLogout} className="p-3 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl hover:bg-green-600 hover:text-white transition-all shadow-lg active:scale-90">
               <LogOut size={18} />
            </button>
          </div>
        </header>
      )}

      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative ${isWizardFlow ? 'p-0 h-screen' : 'px-6 py-6'}`}>
        {renderPortalContent()}
      </main>

      {!isWizardFlow && currentUser && (
        <div className="fixed bottom-8 inset-x-6 z-[70] flex justify-center">
            <nav className="h-20 bg-white/95 dark:bg-slate-950/95 backdrop-blur-2xl flex items-center justify-around px-4 rounded-[2.8rem] shadow-[0_25px_50px_-12px_rgba(0,0,0,0.15)] border border-slate-100 dark:border-white/5 w-full max-w-lg transition-all duration-500">
            {navItems.map(item => (
                <button 
                key={item.id} 
                onClick={() => setPage(item.id)} 
                className={`flex flex-col items-center gap-1 flex-1 py-4 transition-all duration-300 tap-feedback ${currentPage === item.id ? 'text-green-600 scale-110' : 'text-slate-400'}`}
                >
                <item.icon size={24} strokeWidth={currentPage === item.id ? 3 : 2} className={currentPage === item.id ? 'drop-shadow-[0_0_10px_rgba(34,197,94,0.4)]' : ''} />
                <span className={`text-[0.5rem] font-extrabold uppercase tracking-widest ${currentPage === item.id ? 'opacity-100' : 'opacity-60'}`}>{item.label}</span>
                </button>
            ))}
            </nav>
        </div>
      )}
    </div>
  );
};

export default App;
